00203 void Slice::inheritFromPicHeader( PicHeader *picHeader, const PPS *pps, const SPS *sps )
00204 {
00205   if (pps->getRplInfoInPhFlag())
00206   {
00207     setRPL0idx( picHeader->getRPL0idx() );
00208     m_RPL0 = *picHeader->getRPL0();
00209     if(getRPL0idx() != -1)
00210     {
00211       m_RPL0 = *sps->getRPLList0()->getReferencePictureList(getRPL0idx());
00212     }
00213 
00214     setRPL1idx( picHeader->getRPL1idx() );
00215     m_RPL1 = *picHeader->getRPL1();
00216     if(getRPL1idx() != -1)
00217     {
00218       m_RPL1 = *sps->getRPLList1()->getReferencePictureList(getRPL1idx());
00219     }
00220   }
00221 
00222   setDeblockingFilterDisable( picHeader->getDeblockingFilterDisable() );
00223   setDeblockingFilterBetaOffsetDiv2( picHeader->getDeblockingFilterBetaOffsetDiv2() );
00224   setDeblockingFilterTcOffsetDiv2( picHeader->getDeblockingFilterTcOffsetDiv2() );
00225   if (pps->getPPSChromaToolFlag())
00226   {
00227     setDeblockingFilterCbBetaOffsetDiv2 ( picHeader->getDeblockingFilterCbBetaOffsetDiv2() );
00228     setDeblockingFilterCbTcOffsetDiv2   ( picHeader->getDeblockingFilterCbTcOffsetDiv2()   );
00229     setDeblockingFilterCrBetaOffsetDiv2 ( picHeader->getDeblockingFilterCrBetaOffsetDiv2() );
00230     setDeblockingFilterCrTcOffsetDiv2   ( picHeader->getDeblockingFilterCrTcOffsetDiv2()   );
00231   }
00232   else
00233   {
00234     setDeblockingFilterCbBetaOffsetDiv2 ( getDeblockingFilterBetaOffsetDiv2() );
00235     setDeblockingFilterCbTcOffsetDiv2   ( getDeblockingFilterTcOffsetDiv2()   );
00236     setDeblockingFilterCrBetaOffsetDiv2 ( getDeblockingFilterBetaOffsetDiv2() );
00237     setDeblockingFilterCrTcOffsetDiv2   ( getDeblockingFilterTcOffsetDiv2()   );
00238   }
00239 
00240   setSaoEnabledFlag(CHANNEL_TYPE_LUMA,     picHeader->getSaoEnabledFlag(CHANNEL_TYPE_LUMA));
00241   setSaoEnabledFlag(CHANNEL_TYPE_CHROMA,   picHeader->getSaoEnabledFlag(CHANNEL_TYPE_CHROMA));
00242 
00243   setTileGroupAlfEnabledFlag(COMPONENT_Y,  picHeader->getAlfEnabledFlag(COMPONENT_Y));
00244   setTileGroupAlfEnabledFlag(COMPONENT_Cb, picHeader->getAlfEnabledFlag(COMPONENT_Cb));
00245   setTileGroupAlfEnabledFlag(COMPONENT_Cr, picHeader->getAlfEnabledFlag(COMPONENT_Cr));
00246   setTileGroupNumAps(picHeader->getNumAlfAps());
00247   setAlfAPSs(picHeader->getAlfAPSs());
00248   setTileGroupApsIdChroma(picHeader->getAlfApsIdChroma());
00249   setTileGroupCcAlfCbEnabledFlag(picHeader->getCcAlfEnabledFlag(COMPONENT_Cb));
00250   setTileGroupCcAlfCrEnabledFlag(picHeader->getCcAlfEnabledFlag(COMPONENT_Cr));
00251   setTileGroupCcAlfCbApsId(picHeader->getCcAlfCbApsId());
00252   setTileGroupCcAlfCrApsId(picHeader->getCcAlfCrApsId());
00253   m_ccAlfFilterParam.ccAlfFilterEnabled[COMPONENT_Cb - 1] = picHeader->getCcAlfEnabledFlag(COMPONENT_Cb);
00254   m_ccAlfFilterParam.ccAlfFilterEnabled[COMPONENT_Cr - 1] = picHeader->getCcAlfEnabledFlag(COMPONENT_Cr);
00255 }
