00257 void Slice::setNumSubstream(const SPS* sps, const PPS* pps)
00258 {
00259   uint32_t ctuAddr, ctuX, ctuY;
00260   m_numSubstream = 0;
00261 
00262   // count the number of CTUs that align with either the start of a tile, or with an entropy coding sync point
00263   // ignore the first CTU since it doesn't count as an entry point
00264   for (uint32_t i = 1; i < m_sliceMap.getNumCtuInSlice(); i++)
00265   {
00266     ctuAddr = m_sliceMap.getCtuAddrInSlice(i);
00267     ctuX    = (ctuAddr % pps->getPicWidthInCtu());
00268     ctuY    = (ctuAddr / pps->getPicWidthInCtu());
00269 
00270     if (pps->ctuIsTileColBd(ctuX) && (pps->ctuIsTileRowBd(ctuY) || sps->getEntropyCodingSyncEnabledFlag()))
00271     {
00272       m_numSubstream++;
00273     }
00274   }
00275 }
00276 
00277 void Slice::setNumEntryPoints(const SPS *sps, const PPS *pps)
00278 {
00279   uint32_t ctuAddr, ctuX, ctuY;
00280   uint32_t prevCtuAddr, prevCtuX, prevCtuY;
00281   m_numEntryPoints = 0;
00282 
00283   if (!sps->getEntryPointsPresentFlag())
00284   {
00285     return;
00286   }
00287 
00288   // count the number of CTUs that align with either the start of a tile, or with an entropy coding sync point
00289   // ignore the first CTU since it doesn't count as an entry point
00290   for( uint32_t i = 1; i < m_sliceMap.getNumCtuInSlice(); i++ )
00291   {
00292     ctuAddr = m_sliceMap.getCtuAddrInSlice( i );
00293     ctuX = ( ctuAddr % pps->getPicWidthInCtu() );
00294     ctuY = ( ctuAddr / pps->getPicWidthInCtu() );
00295     prevCtuAddr = m_sliceMap.getCtuAddrInSlice(i - 1);
00296     prevCtuX    = (prevCtuAddr % pps->getPicWidthInCtu());
00297     prevCtuY    = (prevCtuAddr / pps->getPicWidthInCtu());
00298 
00299     if (pps->ctuToTileRowBd(ctuY) != pps->ctuToTileRowBd(prevCtuY) || pps->ctuToTileColBd(ctuX) != pps->ctuToTileColBd(prevCtuX) || (ctuY != prevCtuY && sps->getEntropyCodingSyncEnabledFlag()))
00300     {
00301       m_numEntryPoints++;
00302     }
00303   }
00304 }
