00326 void Slice::sortPicList(PicList &picList)
00327 {
00328   picList.sort([](Picture *const &a, Picture *const &b) {
00329     return a->getPOC() < b->getPOC() || (a->getPOC() == b->getPOC() && a->layerId < b->layerId);
00330   });
00331 }
00332 
00333 Picture* Slice::xGetRefPic( PicList& rcListPic, const int poc, const int layerId )
00334 {
00335   // return a nullptr, if picture is not found
00336   Picture* refPic = nullptr;
00337 
00338   for ( auto &currPic : rcListPic )
00339   {
00340     if( currPic->getPOC() == poc && currPic->layerId == layerId )
00341     {
00342       refPic = currPic;
00343       break;
00344     }
00345   }
00346   return  refPic;
00347 }
00348 
00349 Picture* Slice::xGetLongTermRefPic( PicList& rcListPic, const int poc, const bool pocHasMsb, const int layerId )
00350 {
00351   // return a nullptr, if picture is not found or the found picture is not long-term
00352   Picture*  refPic = nullptr;
00353   const int pocCycle = 1 << getSPS()->getBitsForPOC();
00354 
00355   const int refPoc = pocHasMsb ? poc : (poc & (pocCycle - 1));
00356 
00357   for ( auto &currPic : rcListPic )
00358   {
00359     if( currPic->getPOC() != this->getPOC() && currPic->referenced && currPic->layerId == layerId )
00360     {
00361       int currPicPoc = pocHasMsb ? currPic->getPOC() : (currPic->getPOC() & (pocCycle - 1));
00362       if (refPoc == currPicPoc)
00363       {
00364         if(currPic->longTerm)
00365         {
00366           refPic = currPic;
00367         }
00368         break;
00369       }
00370     }
00371   }
00372 
00373   return refPic;
00374 }
00375 
00376 Picture* Slice::xGetLongTermRefPicCandidate( PicList& rcListPic, const int poc, const bool pocHasMsb, const int layerId )
00377 {
00378   // return a nullptr, if picture is not found (might be a short-term or a long-term)
00379   Picture*  refPic = nullptr;
00380   const int pocCycle = 1 << getSPS()->getBitsForPOC();
00381 
00382   const int refPoc = pocHasMsb ? poc : (poc & (pocCycle - 1));
00383 
00384   for ( auto &currPic : rcListPic )
00385   {
00386     if( currPic->getPOC() != this->getPOC() && currPic->referenced && currPic->layerId == layerId )
00387     {
00388       int currPicPoc = pocHasMsb ? currPic->getPOC() : (currPic->getPOC() & (pocCycle - 1));
00389       if (refPoc == currPicPoc)
00390       {
00391         refPic = currPic;
00392         break;
00393       }
00394     }
00395   }
00396 
00397   return refPic;
00398 }
