00412 void Slice::setList1IdxToList0Idx()
00413 {
00414   int idxL0, idxL1;
00415   for ( idxL1 = 0; idxL1 < getNumRefIdx( REF_PIC_LIST_1 ); idxL1++ )
00416   {
00417     m_list1IdxToList0Idx[idxL1] = -1;
00418     for ( idxL0 = 0; idxL0 < getNumRefIdx( REF_PIC_LIST_0 ); idxL0++ )
00419     {
00420       if ( m_apcRefPicList[REF_PIC_LIST_0][idxL0]->getPOC() == m_apcRefPicList[REF_PIC_LIST_1][idxL1]->getPOC() )
00421       {
00422         m_list1IdxToList0Idx[idxL1] = idxL0;
00423         break;
00424       }
00425     }
00426   }
