00428 
00429 void Slice::constructRefPicList(PicList& rcListPic)
00430 {
00431   ::memset(m_bIsUsedAsLongTerm, 0, sizeof(m_bIsUsedAsLongTerm));
00432   if (m_eSliceType == I_SLICE)
00433   {
00434     ::memset(m_apcRefPicList, 0, sizeof(m_apcRefPicList));
00435     ::memset(m_aiNumRefIdx, 0, sizeof(m_aiNumRefIdx));
00436     return;
00437   }
00438 
00439   Picture*  pcRefPic = NULL;
00440   uint32_t numOfActiveRef = 0;
00441   //construct L0
00442   numOfActiveRef = getNumRefIdx(REF_PIC_LIST_0);
00443   int layerIdx = m_pcPic->cs->vps == nullptr ? 0 : m_pcPic->cs->vps->getGeneralLayerIdx( m_pcPic->layerId );
00444 
00445   for (int ii = 0; ii < m_RPL0.getNumRefEntries(); ii++)
00446   {
00447     if( m_RPL0.isInterLayerRefPic( ii ) )
00448     {
00449       CHECK( m_RPL0.getInterLayerRefPicIdx( ii ) == NOT_VALID, "Wrong ILRP index" );
00450 
00451       int refLayerId = m_pcPic->cs->vps->getLayerId( m_pcPic->cs->vps->getDirectRefLayerIdx( layerIdx, m_RPL0.getInterLayerRefPicIdx( ii ) ) );
00452 
00453       pcRefPic = xGetRefPic( rcListPic, getPOC(), refLayerId );
00454       pcRefPic->longTerm = true;
00455     }
00456     else
00457     if (!m_RPL0.isRefPicLongterm(ii))
00458     {
00459       pcRefPic = xGetRefPic(rcListPic, getPOC() + m_RPL0.getRefPicIdentifier(ii), m_pcPic->layerId);
00460       pcRefPic->longTerm = false;
00461     }
00462     else
00463     {
00464       int pocBits = getSPS()->getBitsForPOC();
00465       int pocMask = (1 << pocBits) - 1;
00466       int ltrpPoc = m_RPL0.getRefPicIdentifier(ii) & pocMask;
00467       if(m_RPL0.getDeltaPocMSBPresentFlag(ii))
00468       {
00469         ltrpPoc += getPOC() - m_RPL0.getDeltaPocMSBCycleLT(ii) * (pocMask + 1) - (getPOC() & pocMask);
00470       }
00471       pcRefPic = xGetLongTermRefPicCandidate( rcListPic, ltrpPoc, m_RPL0.getDeltaPocMSBPresentFlag( ii ), m_pcPic->layerId );
00472       pcRefPic->longTerm = true;
00473     }
00474     if(ii < numOfActiveRef)
00475     {
00476       pcRefPic->extendPicBorder( getPPS() );
00477       m_apcRefPicList[REF_PIC_LIST_0][ii] = pcRefPic;
00478       m_bIsUsedAsLongTerm[REF_PIC_LIST_0][ii] = pcRefPic->longTerm;
00479     }
00480   }
00481 
00482   //construct L1
00483   numOfActiveRef = getNumRefIdx(REF_PIC_LIST_1);
00484   for (int ii = 0; ii < m_RPL1.getNumRefEntries(); ii++)
00485   {
00486     if( m_RPL1.isInterLayerRefPic( ii ) )
00487     {
00488       CHECK( m_RPL1.getInterLayerRefPicIdx( ii ) == NOT_VALID, "Wrong ILRP index" );
00489 
00490       int refLayerId = m_pcPic->cs->vps->getLayerId( m_pcPic->cs->vps->getDirectRefLayerIdx( layerIdx, m_RPL1.getInterLayerRefPicIdx( ii ) ) );
00491 
00492       pcRefPic = xGetRefPic( rcListPic, getPOC(), refLayerId );
00493       pcRefPic->longTerm = true;
00494     }
00495     else
00496     if (!m_RPL1.isRefPicLongterm(ii))
00497     {
00498       pcRefPic = xGetRefPic(rcListPic, getPOC() + m_RPL1.getRefPicIdentifier(ii), m_pcPic->layerId);
00499       pcRefPic->longTerm = false;
00500     }
00501     else
00502     {
00503       int pocBits = getSPS()->getBitsForPOC();
00504       int pocMask = (1 << pocBits) - 1;
00505       int ltrpPoc = m_RPL1.getRefPicIdentifier(ii) & pocMask;
00506       if(m_RPL1.getDeltaPocMSBPresentFlag(ii))
00507       {
00508         ltrpPoc += getPOC() - m_RPL1.getDeltaPocMSBCycleLT(ii) * (pocMask + 1) - (getPOC() & pocMask);
00509       }
00510       pcRefPic = xGetLongTermRefPicCandidate( rcListPic, ltrpPoc, m_RPL1.getDeltaPocMSBPresentFlag( ii ), m_pcPic->layerId );
00511       pcRefPic->longTerm = true;
00512     }
00513     if(ii < numOfActiveRef)
00514     {
00515       pcRefPic->extendPicBorder( getPPS() );
00516       m_apcRefPicList[REF_PIC_LIST_1][ii] = pcRefPic;
00517       m_bIsUsedAsLongTerm[REF_PIC_LIST_1][ii] = pcRefPic->longTerm;
00518     }
00519   }
00520 }
