00522 void Slice::initEqualRef()
00523 {
00524   for (int iDir = 0; iDir < NUM_REF_PIC_LIST_01; iDir++)
00525   {
00526     for (int iRefIdx1 = 0; iRefIdx1 < MAX_NUM_REF; iRefIdx1++)
00527     {
00528       for (int iRefIdx2 = iRefIdx1; iRefIdx2 < MAX_NUM_REF; iRefIdx2++)
00529       {
00530         m_abEqualRef[iDir][iRefIdx1][iRefIdx2] = m_abEqualRef[iDir][iRefIdx2][iRefIdx1] = (iRefIdx1 == iRefIdx2? true : false);
00531       }
00532     }
00533   }
