00536 void Slice::checkColRefIdx(uint32_t curSliceSegmentIdx, const Picture* pic)
00537 {
00538   int i;
00539   Slice* curSlice = pic->slices[curSliceSegmentIdx];
00540   int currColRefPOC =  curSlice->getRefPOC( RefPicList(1 - curSlice->getColFromL0Flag()), curSlice->getColRefIdx());
00541 
00542   for(i=curSliceSegmentIdx-1; i>=0; i--)
00543   {
00544     const Slice* preSlice = pic->slices[i];
00545     if(preSlice->getSliceType() != I_SLICE)
00546     {
00547       const int preColRefPOC  = preSlice->getRefPOC( RefPicList(1 - preSlice->getColFromL0Flag()), preSlice->getColRefIdx());
00548       if(currColRefPOC != preColRefPOC)
00549       {
00550         THROW("sh_collocated_ref_idx shall always be the same for all slices of a coded picture!");
00551       }
00552       else
00553       {
00554         break;
00555       }
00556     }
00557   }
00558 }
