00560 void Slice::checkCRA(const ReferencePictureList* pRPL0, const ReferencePictureList* pRPL1, const int pocCRA, PicList& rcListPic)
00561 {
00562   if (pocCRA < MAX_UINT && getPOC() > pocCRA)
00563   {
00564     uint32_t numRefPic = pRPL0->getNumberOfShorttermPictures() + pRPL0->getNumberOfLongtermPictures();
00565     for (int i = 0; i < numRefPic; i++)
00566     {
00567       if (!pRPL0->isRefPicLongterm(i))
00568       {
00569         CHECK(getPOC() + pRPL0->getRefPicIdentifier(i) < pocCRA, "Invalid state");
00570       }
00571       else if (!pRPL0->isInterLayerRefPic(i))
00572       {
00573         int pocBits = getSPS()->getBitsForPOC();
00574         int pocMask = (1 << pocBits) - 1;
00575         int ltrpPoc = pRPL0->getRefPicIdentifier(i) & pocMask;
00576         if(pRPL0->getDeltaPocMSBPresentFlag(i))
00577         {
00578           ltrpPoc += getPOC() - pRPL0->getDeltaPocMSBCycleLT(i) * (pocMask + 1) - (getPOC() & pocMask);
00579         }
00580         const Picture *ltrp =
00581           xGetLongTermRefPic(rcListPic, ltrpPoc, pRPL0->getDeltaPocMSBPresentFlag(i), m_pcPic->layerId);
00582         CHECK(ltrp == nullptr, "Long-term pic not found");
00583         CHECK(ltrp->getPOC() < pocCRA, "Invalid state");
00584       }
00585     }
00586     numRefPic = pRPL1->getNumberOfShorttermPictures() + pRPL1->getNumberOfLongtermPictures();
00587     for (int i = 0; i < numRefPic; i++)
00588     {
00589       if (!pRPL1->isRefPicLongterm(i))
00590       {
00591         CHECK(getPOC() + pRPL1->getRefPicIdentifier(i) < pocCRA, "Invalid state");
00592       }
00593       else if( !pRPL1->isInterLayerRefPic( i ) )
00594       {
00595         int pocBits = getSPS()->getBitsForPOC();
00596         int pocMask = (1 << pocBits) - 1;
00597         int ltrpPoc = pRPL1->getRefPicIdentifier(i) & pocMask;
00598         if(pRPL1->getDeltaPocMSBPresentFlag(i))
00599         {
00600           ltrpPoc += getPOC() - pRPL1->getDeltaPocMSBCycleLT(i) * (pocMask + 1) - (getPOC() & pocMask);
00601         }
00602         const Picture *ltrp =
00603           xGetLongTermRefPic(rcListPic, ltrpPoc, pRPL1->getDeltaPocMSBPresentFlag(i), m_pcPic->layerId);
00604         CHECK(ltrp == nullptr, "Long-term pic not found");
00605         CHECK(ltrp->getPOC() < pocCRA, "Invalid state");
00606       }
00607     }
00608   }
00609 }
00610 
00611 void Slice::checkRPL(const ReferencePictureList* pRPL0, const ReferencePictureList* pRPL1, const int associatedIRAPDecodingOrderNumber, PicList& rcListPic)
00612 {
00613   Picture* pcRefPic;
00614   int refPicPOC;
00615   int refPicDecodingOrderNumber;
00616 
00617   int irapPOC = getAssociatedIRAPPOC();
00618 
00619   const int numEntries[] = { pRPL0->getNumberOfShorttermPictures() + pRPL0->getNumberOfLongtermPictures() + pRPL0->getNumberOfInterLayerPictures(), pRPL1->getNumberOfShorttermPictures() + pRPL1->getNumberOfLongtermPictures() + pRPL1->getNumberOfInterLayerPictures() };
00620   const int numActiveEntries[] = { getNumRefIdx( REF_PIC_LIST_0 ), getNumRefIdx( REF_PIC_LIST_1 ) };
00621   const ReferencePictureList* rpl[] = { pRPL0, pRPL1 };
00622   const bool fieldSeqFlag = getSPS()->getFieldSeqFlag();
00623   const int layerIdx = m_pcPic->cs->vps == nullptr ? 0 : m_pcPic->cs->vps->getGeneralLayerIdx( m_pcPic->layerId );
00624 
00625   for( int refPicList = 0; refPicList < 2; refPicList++ )
00626   {
00627     for( int i = 0; i < numEntries[refPicList]; i++ )
00628     {
00629       if( rpl[refPicList]->isInterLayerRefPic( i ) )
00630       {
00631         int refLayerId = m_pcPic->cs->vps->getLayerId( m_pcPic->cs->vps->getDirectRefLayerIdx( layerIdx, rpl[refPicList]->getInterLayerRefPicIdx( i ) ) );
00632         pcRefPic = xGetRefPic( rcListPic, getPOC(), refLayerId );
00633         refPicPOC = pcRefPic->getPOC();
00634       }
00635       else if( !rpl[refPicList]->isRefPicLongterm( i ) )
00636       {
00637         refPicPOC = getPOC() + rpl[refPicList]->getRefPicIdentifier(i);
00638         pcRefPic = xGetRefPic( rcListPic, refPicPOC, m_pcPic->layerId );
00639       }
00640       else
00641       {
00642         int pocBits = getSPS()->getBitsForPOC();
00643         int pocMask = ( 1 << pocBits ) - 1;
00644         int ltrpPoc = rpl[refPicList]->getRefPicIdentifier( i ) & pocMask;
00645         if( rpl[refPicList]->getDeltaPocMSBPresentFlag( i ) )
00646         {
00647           ltrpPoc += getPOC() - rpl[refPicList]->getDeltaPocMSBCycleLT( i ) * ( pocMask + 1 ) - ( getPOC() & pocMask );
00648         }
00649         pcRefPic = xGetLongTermRefPic( rcListPic, ltrpPoc, rpl[refPicList]->getDeltaPocMSBPresentFlag( i ), m_pcPic->layerId );
00650         refPicPOC = pcRefPic->getPOC();
00651       }
00652       if (pcRefPic) // the checks are for all reference picture, but we may not have an inactive reference picture, if starting with a CRA
00653       {
00654         refPicDecodingOrderNumber = pcRefPic->getDecodingOrderNumber();
00655 
00656         if( m_eNalUnitType == NAL_UNIT_CODED_SLICE_CRA || m_eNalUnitType == NAL_UNIT_CODED_SLICE_IDR_W_RADL || m_eNalUnitType == NAL_UNIT_CODED_SLICE_IDR_N_LP )
00657         {
00658           CHECK( refPicPOC < irapPOC || refPicDecodingOrderNumber < associatedIRAPDecodingOrderNumber, "When the current picture, with nuh_layer_id equal to a particular value layerId, "
00659             "is an IRAP picture, there shall be no picture referred to by an entry in RefPicList[ 0 ] that precedes, in output order or decoding order, any preceding IRAP picture "
00660             "with nuh_layer_id equal to layerId in decoding order (when present)." );
00661         }
00662 
00663         if( irapPOC < getPOC() && !fieldSeqFlag )
00664         {
00665           CHECK( refPicPOC < irapPOC || refPicDecodingOrderNumber < associatedIRAPDecodingOrderNumber, "When the current picture follows an IRAP picture having the same value "
00666             "of nuh_layer_id and the leading pictures, if any, associated with that IRAP picture, in both decoding order and output order, there shall be no picture referred "
00667             "to by an entry in RefPicList[ 0 ] or RefPicList[ 1 ] that precedes that IRAP picture in output order or decoding order." );
00668         }
00669 
00670         // Generated reference picture does not have picture header
00671         const bool isGeneratedRefPic = pcRefPic->slices[0]->getPicHeader() ? false : true;
00672 
00673         const bool nonReferencePictureFlag = isGeneratedRefPic ? pcRefPic->slices[0]->getPicHeader()->getNonReferencePictureFlag() : pcRefPic->nonReferencePictureFlag;
00674         CHECK( pcRefPic == m_pcPic || nonReferencePictureFlag, "The picture referred to by each entry in RefPicList[ 0 ] or RefPicList[ 1 ] shall not be the current picture and shall have ph_non_ref_pic_flag equal to 0" );
00675 
00676         if( i < numActiveEntries[refPicList] )
00677         {
00678           if( irapPOC < getPOC() )
00679           {
00680             CHECK( refPicPOC < irapPOC || refPicDecodingOrderNumber < associatedIRAPDecodingOrderNumber, "When the current picture follows an IRAP picture having the same value "
00681               "of nuh_layer_id in both decoding order and output order, there shall be no picture referred to by an active entry in RefPicList[ 0 ] or RefPicList[ 1 ] that "
00682               "precedes that IRAP picture in output order or decoding order." );
00683           }
00684 
00685           // Checking this: "When the current picture is a RADL picture, there shall be no active entry in RefPicList[ 0 ] or
00686           // RefPicList[ 1 ] that is any of the following: A picture that precedes the associated IRAP picture in decoding order"
00687           if( m_eNalUnitType == NAL_UNIT_CODED_SLICE_RADL )
00688           {
00689             CHECK( refPicDecodingOrderNumber < associatedIRAPDecodingOrderNumber, "RADL picture detected that violate the rule that no active entry in RefPicList[] shall precede the associated IRAP picture in decoding order" );
00690 #if JVET_S0084_S0110_RADL
00691             // Checking this: "When the current picture is a RADL picture, there shall be no active entry in RefPicList[ 0 ] or 
00692             // RefPicList[ 1 ] that is any of the following: A RASL picture with pps_mixed_nalu_types_in_pic_flag is equal to 0
00693             for (int i = 0; i < pcRefPic->numSlices; i++)
00694             {
00695               if (pcRefPic->slices[i]->getPPS()->getMixedNaluTypesInPicFlag() == 0)
00696               {
00697                 CHECK(pcRefPic->slices[i]->getNalUnitType() == NAL_UNIT_CODED_SLICE_RASL, "When the current picture is a RADL picture, there shall be no active entry in RefPicList[ 0 ] or RefPicList[ 1 ] that is a RASL picture with pps_mixed_nalu_types_in_pic_flag is equal to 0");
00698               }
00699             }
00700 #endif
00701 
00702           }
00703 
00704           CHECK( pcRefPic->temporalId > m_pcPic->temporalId, "The picture referred to by each active entry in RefPicList[ 0 ] or RefPicList[ 1 ] shall be present in the DPB and shall have TemporalId less than or equal to that of the current picture." );
00705         }
00706 #if JVET_R0046_IRAP_ASPECT2
00707         // Add a constraint on an ILRP being either an IRAP picture or having TemporalId less than or equal to
00708         // Max (0, vps_max_tid_il_ref_pics_plus1[ refPicVpsLayerId ] - 1 ), with refPicVpsLayerId equal to the value of
00709         // the nuh_layer_id of the referenced picture.
00710         if (rpl[refPicList]->isInterLayerRefPic(i))
00711         {
00712           bool cond1      = (pcRefPic->getPictureType() == NAL_UNIT_CODED_SLICE_GDR);
00713           bool cond2      = (pcRefPic->slices[0]->getPicHeader()->getRecoveryPocCnt() == 0);
00714           bool cond3      = (pcRefPic->cs->slice->isIRAP());
00715           
00716           const VPS *vps                  = pcRefPic->cs->vps;
00717           const int  maxTidILRefPicsPlus1 = vps->getMaxTidIlRefPicsPlus1(layerIdx, pcRefPic->layerId);
00718           bool cond4 = (pcRefPic->temporalId < maxTidILRefPicsPlus1);
00719 
00720           CHECK((cond1 && cond2) || cond3 || cond4,
00721                 "Either of the following conditions shall apply for the picture referred to by each ILRP entry, when "
00722                 "present, in RefPicList[ 0 ] or RefPicList[ 1 ] of a slice of the current picture:-The picture is a "
00723                 "GDR picture with "
00724                 "ph_recovery_poc_cnt equal to 0 or an IRAP picture."
00725                 "-The picture has TemporalId less than vps_max_tid_il_ref_pics_plus1[ currLayerIdx ][ refLayerIdx ], "
00726                 "where currLayerIdx and refLayerIdx are equal to "
00727                 "GeneralLayerIdx[ nuh_layer_id ] and GeneralLayerIdx[ refpicLayerId ], respectively. ");
00728         }
00729 #endif
00730       }
00731     }
00732   }
00733 }
00734 
00735 void Slice::checkSTSA(PicList& rcListPic)
00736 {
00737   int ii;
00738   Picture* pcRefPic = NULL;
00739   int numOfActiveRef = getNumRefIdx(REF_PIC_LIST_0);
00740 
00741   for (ii = 0; ii < numOfActiveRef; ii++)
00742   {
00743     pcRefPic = m_apcRefPicList[REF_PIC_LIST_0][ii];
00744 
00745     if( m_eNalUnitType == NAL_UNIT_CODED_SLICE_STSA && pcRefPic->layerId == m_pcPic->layerId )
00746     {
00747       CHECK( pcRefPic->temporalId == m_uiTLayer, "When the current picture is an STSA picture and nuh_layer_id equal to that of the current picture, there shall be no active entry in the RPL that has TemporalId equal to that of the current picture" );
00748     }
00749 
00750     // Checking this: "When the current picture is a picture that follows, in decoding order, an STSA picture that has TemporalId equal to that of the current picture, there shall be no
00751     // picture that has TemporalId equal to that of the current picture included as an active entry in RefPicList[ 0 ] or RefPicList[ 1 ] that precedes the STSA picture in decoding order."
00752     CHECK(pcRefPic->subLayerNonReferencePictureDueToSTSA, "The RPL of the current picture contains a picture that is not allowed in this temporal layer due to an earlier STSA picture");
00753   }
00754 
00755   numOfActiveRef = getNumRefIdx(REF_PIC_LIST_1);
00756   for (ii = 0; ii < numOfActiveRef; ii++)
00757   {
00758     pcRefPic = m_apcRefPicList[REF_PIC_LIST_1][ii];
00759 
00760     if( m_eNalUnitType == NAL_UNIT_CODED_SLICE_STSA && pcRefPic->layerId == m_pcPic->layerId )
00761     {
00762       CHECK( pcRefPic->temporalId == m_uiTLayer, "When the current picture is an STSA picture and nuh_layer_id equal to that of the current picture, there shall be no active entry in the RPL that has TemporalId equal to that of the current picture" );
00763     }
00764 
00765     // Checking this: "When the current picture is a picture that follows, in decoding order, an STSA picture that has TemporalId equal to that of the current picture, there shall be no
00766     // picture that has TemporalId equal to that of the current picture included as an active entry in RefPicList[ 0 ] or RefPicList[ 1 ] that precedes the STSA picture in decoding order."
00767     CHECK(pcRefPic->subLayerNonReferencePictureDueToSTSA, "The active RPL part of the current picture contains a picture that is not allowed in this temporal layer due to an earlier STSA picture");
00768   }
00769 
00770   // If the current picture is an STSA picture, make all reference pictures in the DPB with temporal
00771   // id equal to the temproal id of the current picture sub-layer non-reference pictures. The flag
00772   // subLayerNonReferencePictureDueToSTSA equal to true means that the picture may not be used for
00773   // reference by a picture that follows the current STSA picture in decoding order
00774   if (getNalUnitType() == NAL_UNIT_CODED_SLICE_STSA)
00775   {
00776     PicList::iterator iterPic = rcListPic.begin();
00777     while (iterPic != rcListPic.end())
00778     {
00779       pcRefPic = *(iterPic++);
00780       if (!pcRefPic->referenced || pcRefPic->getPOC() == m_iPOC)
00781       {
00782         continue;
00783       }
00784 
00785       if (pcRefPic->temporalId == m_uiTLayer)
00786       {
00787         pcRefPic->subLayerNonReferencePictureDueToSTSA = true;
00788       }
00789     }
00790   }
00791 }
00792 
00793 
00812 void Slice::decodingRefreshMarking(int& pocCRA, bool& bRefreshPending, PicList& rcListPic, const bool bEfficientFieldIRAPEnabled)
00813 {
00814   Picture* rpcPic;
00815   int      pocCurr = getPOC();
00816 
00817   if ( getNalUnitType() == NAL_UNIT_CODED_SLICE_IDR_W_RADL
00818     || getNalUnitType() == NAL_UNIT_CODED_SLICE_IDR_N_LP)  // IDR picture
00819   {
00820     // mark all pictures as not used for reference
00821     PicList::iterator        iterPic       = rcListPic.begin();
00822     while (iterPic != rcListPic.end())
00823     {
00824       rpcPic = *(iterPic);
00825       if (rpcPic->getPOC() != pocCurr)
00826       {
00827         rpcPic->referenced = false;
00828         rpcPic->getHashMap()->clearAll();
00829       }
00830       iterPic++;
00831     }
00832     if (bEfficientFieldIRAPEnabled)
00833     {
00834       bRefreshPending = true;
00835     }
00836   }
00837   else // CRA or No DR
00838   {
00839     if(bEfficientFieldIRAPEnabled && (getAssociatedIRAPType() == NAL_UNIT_CODED_SLICE_IDR_N_LP || getAssociatedIRAPType() == NAL_UNIT_CODED_SLICE_IDR_W_RADL))
00840     {
00841       if (bRefreshPending==true && pocCurr > m_iLastIDR) // IDR reference marking pending
00842       {
00843         PicList::iterator        iterPic       = rcListPic.begin();
00844         while (iterPic != rcListPic.end())
00845         {
00846           rpcPic = *(iterPic);
00847           if (rpcPic->getPOC() != pocCurr && rpcPic->getPOC() != m_iLastIDR)
00848           {
00849             rpcPic->referenced = false;
00850             rpcPic->getHashMap()->clearAll();
00851           }
00852           iterPic++;
00853         }
00854         bRefreshPending = false;
00855       }
00856     }
00857     else
00858     {
00859       if (bRefreshPending==true && pocCurr > pocCRA) // CRA reference marking pending
00860       {
00861         PicList::iterator iterPic = rcListPic.begin();
00862         while (iterPic != rcListPic.end())
00863         {
00864           rpcPic = *(iterPic);
00865           if (rpcPic->getPOC() != pocCurr && rpcPic->getPOC() != pocCRA)
00866           {
00867             rpcPic->referenced = false;
00868             rpcPic->getHashMap()->clearAll();
00869           }
00870           iterPic++;
00871         }
00872         bRefreshPending = false;
00873       }
00874     }
00875     if ( getNalUnitType() == NAL_UNIT_CODED_SLICE_CRA ) // CRA picture found
00876     {
00877       bRefreshPending = true;
00878       pocCRA = pocCurr;
00879     }
00880   }
00881 }
