00892   m_iSliceQp             = pSrc->m_iSliceQp;
00893   m_iSliceQpBase         = pSrc->m_iSliceQpBase;
00894   m_ChromaQpAdjEnabled              = pSrc->m_ChromaQpAdjEnabled;
00895   m_deblockingFilterDisable         = pSrc->m_deblockingFilterDisable;
