00900   m_deblockingFilterCbTcOffsetDiv2    = pSrc->m_deblockingFilterCbTcOffsetDiv2;
00901   m_deblockingFilterCrBetaOffsetDiv2  = pSrc->m_deblockingFilterCrBetaOffsetDiv2;
00902   m_deblockingFilterCrTcOffsetDiv2    = pSrc->m_deblockingFilterCrTcOffsetDiv2;
00903   m_depQuantEnabledFlag               = pSrc->m_depQuantEnabledFlag;
00904   m_signDataHidingEnabledFlag         = pSrc->m_signDataHidingEnabledFlag;
00905   m_tsResidualCodingDisabledFlag      = pSrc->m_tsResidualCodingDisabledFlag;
00906 
00907   for (i = 0; i < NUM_REF_PIC_LIST_01; i++)
00908   {
00909     m_aiNumRefIdx[i]     = pSrc->m_aiNumRefIdx[i];
00910   }
00911 
00912   for (i = 0; i < MAX_NUM_REF; i++)
00913   {
00914     m_list1IdxToList0Idx[i] = pSrc->m_list1IdxToList0Idx[i];
00915   }
00916 
00917   m_bCheckLDC             = pSrc->m_bCheckLDC;
00918   m_iSliceQpDelta        = pSrc->m_iSliceQpDelta;
00919 
00920   m_biDirPred = pSrc->m_biDirPred;
00921   m_symRefIdx[0] = pSrc->m_symRefIdx[0];
00922   m_symRefIdx[1] = pSrc->m_symRefIdx[1];
00923 
00924   for (uint32_t component = 0; component < MAX_NUM_COMPONENT; component++)
00925   {
00926     m_iSliceChromaQpDelta[component] = pSrc->m_iSliceChromaQpDelta[component];
00927   }
00928   m_iSliceChromaQpDelta[JOINT_CbCr] = pSrc->m_iSliceChromaQpDelta[JOINT_CbCr];
00929 
00930   for (i = 0; i < NUM_REF_PIC_LIST_01; i++)
00931   {
00932     for (j = 0; j < MAX_NUM_REF; j++)
00933     {
00934       m_apcRefPicList[i][j]  = pSrc->m_apcRefPicList[i][j];
00935       m_aiRefPOCList[i][j]   = pSrc->m_aiRefPOCList[i][j];
00936       m_bIsUsedAsLongTerm[i][j] = pSrc->m_bIsUsedAsLongTerm[i][j];
00937     }
00938     m_bIsUsedAsLongTerm[i][MAX_NUM_REF] = pSrc->m_bIsUsedAsLongTerm[i][MAX_NUM_REF];
00939   }
00940   if( cpyAlmostAll ) m_iDepth = pSrc->m_iDepth;
00941 
00942   // access channel
00943   if (cpyAlmostAll) m_RPL0 = pSrc->m_RPL0;
00944   if (cpyAlmostAll) m_RPL1 = pSrc->m_RPL1;
00945   m_iLastIDR             = pSrc->m_iLastIDR;
00946 
00947   if( cpyAlmostAll ) m_pcPic  = pSrc->m_pcPic;
00948 
00949   m_pcPicHeader          = pSrc->m_pcPicHeader;
00950   m_colFromL0Flag        = pSrc->m_colFromL0Flag;
00951   m_colRefIdx            = pSrc->m_colRefIdx;
00952 
00953   if( cpyAlmostAll ) setLambdas(pSrc->getLambdas());
00954 
00955   for (i = 0; i < NUM_REF_PIC_LIST_01; i++)
00956   {
00957     for (j = 0; j < MAX_NUM_REF; j++)
00958     {
00959       for (k =0; k < MAX_NUM_REF; k++)
00960       {
00961         m_abEqualRef[i][j][k] = pSrc->m_abEqualRef[i][j][k];
00962       }
00963     }
00964   }
00965 
00966   m_uiTLayer                      = pSrc->m_uiTLayer;
