00968 
00969   m_sliceMap                      = pSrc->m_sliceMap;
00970   m_independentSliceIdx           = pSrc->m_independentSliceIdx;
00971   m_nextSlice                     = pSrc->m_nextSlice;
00972   m_clpRngs                       = pSrc->m_clpRngs;
00973   m_lmcsEnabledFlag               = pSrc->m_lmcsEnabledFlag;
00974   m_explicitScalingListUsed       = pSrc->m_explicitScalingListUsed;
00975 
00976   m_pendingRasInit                = pSrc->m_pendingRasInit;
00977 
00978   for ( uint32_t e=0 ; e<NUM_REF_PIC_LIST_01 ; e++ )
00979   {
00980     for ( uint32_t n=0 ; n<MAX_NUM_REF ; n++ )
00981     {
00982       memcpy(m_weightPredTable[e][n], pSrc->m_weightPredTable[e][n], sizeof(WPScalingParam)*MAX_NUM_COMPONENT );
00983     }
00984   }
00985 
00986   for( uint32_t ch = 0 ; ch < MAX_NUM_CHANNEL_TYPE; ch++)
00987   {
00988     m_saoEnabledFlag[ch] = pSrc->m_saoEnabledFlag[ch];
00989   }
00990 
00991   m_cabacInitFlag                 = pSrc->m_cabacInitFlag;
00992   memcpy(m_alfApss, pSrc->m_alfApss, sizeof(m_alfApss)); // this might be quite unsafe
00993   memcpy( m_tileGroupAlfEnabledFlag, pSrc->m_tileGroupAlfEnabledFlag, sizeof(m_tileGroupAlfEnabledFlag));
00994   m_tileGroupNumAps               = pSrc->m_tileGroupNumAps;
00995   m_tileGroupLumaApsId            = pSrc->m_tileGroupLumaApsId;
00996   m_tileGroupChromaApsId          = pSrc->m_tileGroupChromaApsId;
00997   m_disableSATDForRd              = pSrc->m_disableSATDForRd;
00998   m_isLossless = pSrc->m_isLossless;
00999 
01000   if( cpyAlmostAll ) m_encCABACTableIdx  = pSrc->m_encCABACTableIdx;
01001   for( int i = 0; i < NUM_REF_PIC_LIST_01; i ++ )
01002   {
01003     for (int j = 0; j < MAX_NUM_REF_PICS; j ++ )
01004     {
01005       m_scalingRatio[i][j]          = pSrc->m_scalingRatio[i][j];
01006     }
01007   }
01008   m_ccAlfFilterParam                        = pSrc->m_ccAlfFilterParam;
01009   m_ccAlfFilterControl[0]                   = pSrc->m_ccAlfFilterControl[0];
01010   m_ccAlfFilterControl[1]                   = pSrc->m_ccAlfFilterControl[1];
01011   m_tileGroupCcAlfCbEnabledFlag             = pSrc->m_tileGroupCcAlfCbEnabledFlag;
01012   m_tileGroupCcAlfCrEnabledFlag             = pSrc->m_tileGroupCcAlfCrEnabledFlag;
01013   m_tileGroupCcAlfCbApsId                   = pSrc->m_tileGroupCcAlfCbApsId;
01014   m_tileGroupCcAlfCrApsId                   = pSrc->m_tileGroupCcAlfCrApsId;
01015 }
