01020 bool Slice::isTemporalLayerSwitchingPoint(PicList& rcListPic) const
01021 {
01022   // loop through all pictures in the reference picture buffer
01023   PicList::iterator iterPic = rcListPic.begin();
01024   while ( iterPic != rcListPic.end())
01025   {
01026     const Picture* pcPic = *(iterPic++);
01027     if( pcPic->referenced && pcPic->poc != getPOC())
01028     {
01029       if( pcPic->temporalId >= getTLayer())
01030       {
01031         return false;
01032       }
01033     }
01034   }
01035   return true;
01036 }
