01057 
01058 void Slice::checkLeadingPictureRestrictions(PicList& rcListPic, const PPS& pps) const
01059 {
01060   int nalUnitType = this->getNalUnitType();
01061 
01062   // When a picture is a leading picture, it shall be a RADL or RASL picture.
01063   if(this->getAssociatedIRAPPOC() > this->getPOC())
01064   {
01065     //check this only when pps_mixed_nalu_types_in_pic_flag is equal to 0
01066     if (pps.getMixedNaluTypesInPicFlag() == 0)
01067     {
01068       // Do not check IRAP pictures since they may get a POC lower than their associated IRAP
01069       if (nalUnitType < NAL_UNIT_CODED_SLICE_IDR_W_RADL ||
01070           nalUnitType > NAL_UNIT_CODED_SLICE_CRA)
01071       {
01072         CHECK(nalUnitType != NAL_UNIT_CODED_SLICE_RASL &&
01073               nalUnitType != NAL_UNIT_CODED_SLICE_RADL, "Invalid NAL unit type");
01074       }
01075     }
01076   }
01077 
01078   if (this->getAssociatedIRAPPOC() <= this->getPOC())
01079   {
01080     if (pps.getMixedNaluTypesInPicFlag() == 0)
01081     {
01082       CHECK(nalUnitType == NAL_UNIT_CODED_SLICE_RASL || nalUnitType == NAL_UNIT_CODED_SLICE_RADL, "When a picture is not a leading picture, it shall not be a RADL or RASL picture.");
01083     }
01084   }
01085 
01086   // No RASL pictures shall be present in the bitstream that are associated with
01087   // an IDR picture.
01088   if (nalUnitType == NAL_UNIT_CODED_SLICE_RASL && !pps.getMixedNaluTypesInPicFlag())
01089   {
01090     CHECK( this->getAssociatedIRAPType() == NAL_UNIT_CODED_SLICE_IDR_N_LP   ||
01091            this->getAssociatedIRAPType() == NAL_UNIT_CODED_SLICE_IDR_W_RADL, "Invalid NAL unit type");
01092   }
01093 
01094   // No RADL pictures shall be present in the bitstream that are associated with
01095   // a BLA picture having nal_unit_type equal to BLA_N_LP or that are associated
01096   // with an IDR picture having nal_unit_type equal to IDR_N_LP.
01097   if (nalUnitType == NAL_UNIT_CODED_SLICE_RADL && !pps.getMixedNaluTypesInPicFlag())
01098   {
01099     CHECK (this->getAssociatedIRAPType() == NAL_UNIT_CODED_SLICE_IDR_N_LP, "Invalid NAL unit type");
01100   }
01101 
01102   // loop through all pictures in the reference picture buffer
01103   PicList::iterator iterPic = rcListPic.begin();
01104   int numNonLPFound = 0;
01105   while ( iterPic != rcListPic.end())
01106   {
01107     Picture* pcPic = *(iterPic++);
01108     if( ! pcPic->reconstructed)
01109     {
01110       continue;
01111     }
01112     if( pcPic->poc == this->getPOC())
01113     {
01114       continue;
01115     }
01116     const Slice* pcSlice = pcPic->slices[0];
01117 
01118     if (pcSlice->getPicHeader()->getPicOutputFlag() == 1 && !this->getNoOutputOfPriorPicsFlag() && pcPic->layerId == this->m_nuhLayerId)
01119     {
01120       if ((nalUnitType == NAL_UNIT_CODED_SLICE_CRA || nalUnitType == NAL_UNIT_CODED_SLICE_IDR_N_LP || nalUnitType == NAL_UNIT_CODED_SLICE_IDR_W_RADL) && !pps.getMixedNaluTypesInPicFlag())
01121       {
01122         CHECK(pcPic->poc >= this->getPOC(), "Any picture, with nuh_layer_id equal to a particular value layerId, that precedes an IRAP picture with nuh_layer_id "
01123               "equal to layerId in decoding order shall precede the IRAP picture in output order.");
01124       }
01125     }
01126 
01127     if (pcSlice->getPicHeader()->getPicOutputFlag() == 1 && pcPic->layerId == this->m_nuhLayerId)
01128     {
01129       if (nalUnitType == NAL_UNIT_CODED_SLICE_RADL)
01130       {
01131         if (this->getAssociatedIRAPPOC() > pcSlice->getAssociatedIRAPPOC() && !pps.getMixedNaluTypesInPicFlag())
01132         {
01133           if (this->getAssociatedIRAPPOC() != pcPic->poc)
01134           {
01135             CHECK(pcPic->poc >= this->getPOC(), "Any picture, with nuh_layer_id equal to a particular value layerId, that precedes an IRAP picture with nuh_layer_id "
01136                   "equal to layerId in decoding order shall precede any RADL picture associated with the IRAP picture in output order.");
01137           }
01138         }
01139       }
01140     }
01141 
01142     if (pcSlice->getPicHeader()->getPicOutputFlag() == 1 && !this->getPicHeader()->getNoOutputBeforeRecoveryFlag() && pcPic->layerId == this->m_nuhLayerId
01143         && nalUnitType != NAL_UNIT_CODED_SLICE_GDR && this->getPicHeader()->getRecoveryPocCnt() != -1)
01144     {
01145       if (this->getPOC() == this->getPicHeader()->getRecoveryPocCnt() + this->getPrevGDRInSameLayerPOC())
01146       {
01147         CHECK(pcPic->poc >= this->getPOC(), "Any picture, with nuh_layer_id equal to a particular value layerId, that precedes a recovery point picture with "
01148               "nuh_layer_id equal to layerId in decoding order shall precede the recovery point picture in output order.");
01149       }
01150     }
01151 
01152     if ((nalUnitType == NAL_UNIT_CODED_SLICE_RASL || nalUnitType == NAL_UNIT_CODED_SLICE_RADL) && 
01153       (pcSlice->getNalUnitType() != NAL_UNIT_CODED_SLICE_RASL && pcSlice->getNalUnitType() != NAL_UNIT_CODED_SLICE_RADL) && !pps.getMixedNaluTypesInPicFlag())
01154     {
01155       if (pcSlice->getAssociatedIRAPPOC() == this->getAssociatedIRAPPOC() && pcPic->layerId == this->m_nuhLayerId)
01156       {
01157         numNonLPFound++;
01158         int limitNonLP = 0;
01159         if (pcSlice->getSPS()->getFieldSeqFlag())
01160         {
01161           limitNonLP = 1;
01162         }
01163         CHECK(pcPic->poc > this->getAssociatedIRAPPOC() && numNonLPFound > limitNonLP, "If sps_field_seq_flag is equal to 0 and the current picture, with nuh_layer_id "
01164               "equal to a particular value layerId, is a leading picture associated with an IRAP picture, it shall precede, in decoding order, all non-leading "
01165               "pictures that are associated with the same IRAP picture.Otherwise, let picA and picB be the first and the last leading pictures, in decoding order, "
01166               "associated with an IRAP picture, respectively, there shall be at most one non-leading picture with nuh_layer_id equal to layerId preceding picA in "
01167               "decoding order, and there shall be no non-leading picture with nuh_layer_id equal to layerId between picA and picB in decoding order.");
01168       }
01169     }
01170 
01171     if (nalUnitType == NAL_UNIT_CODED_SLICE_RASL && !pps.getMixedNaluTypesInPicFlag())
01172     {
01173       if ((this->getAssociatedIRAPType() == NAL_UNIT_CODED_SLICE_CRA) &&
01174           this->getAssociatedIRAPPOC() == pcSlice->getAssociatedIRAPPOC())
01175       {
01176         if (pcSlice->getNalUnitType() == NAL_UNIT_CODED_SLICE_RADL)
01177         {
01178           CHECK(pcPic->poc <= this->getPOC(), "Any RASL picture associated with a CRA picture shall precede any RADL picture associated with the CRA picture in output order.");
01179         }
01180       }
01181     }
01182 
01183     if (nalUnitType == NAL_UNIT_CODED_SLICE_RASL && !pps.getMixedNaluTypesInPicFlag())
01184     {
01185       if(this->getAssociatedIRAPType() == NAL_UNIT_CODED_SLICE_CRA)
01186       {
01187         if(pcSlice->getPOC() < this->getAssociatedIRAPPOC() &&
01188           (
01189             pcSlice->getNalUnitType() == NAL_UNIT_CODED_SLICE_IDR_N_LP   ||
01190             pcSlice->getNalUnitType() == NAL_UNIT_CODED_SLICE_IDR_W_RADL ||
01191             pcSlice->getNalUnitType() == NAL_UNIT_CODED_SLICE_CRA ||
01192             pcSlice->getNalUnitType() == NAL_UNIT_CODED_SLICE_GDR) &&
01193             pcPic->layerId == this->m_nuhLayerId)
01194         {
01195           CHECK(this->getPOC() <= pcSlice->getPOC(), "Any RASL picture, with nuh_layer_id equal to a particular value layerId, associated with a CRA picture shall follow, "
01196                "in output order, any IRAP or GDR picture with nuh_layer_id equal to layerId that precedes the CRA picture in decoding order.");
01197         }
01198       }
01199     }
01200   }
01201 }
01202 
01203 void Slice::checkSubpicTypeConstraints(PicList& rcListPic, const ReferencePictureList* pRPL0, const ReferencePictureList* pRPL1, const int prevIRAPSubpicDecOrderNo)
01204 {
01205   int curSubpicIdx = getPPS()->getSubPicIdxFromSubPicId(getSliceSubPicId());
01206 
01207   if (getPPS()->getMixedNaluTypesInPicFlag() && getSliceType() != I_SLICE)
01208   {
01209     CHECK(!getSPS()->getSubPicTreatedAsPicFlag(curSubpicIdx), "When pps_mixed_nalu_types_in_pic_flag is equal 1, the value of sps_subpic_treated_as_pic_flag shall be equal to 1 "
01210           "for all the subpictures that are in the picture and contain at least one P or B slice");
01211   }
01212 
01213   int nalUnitType = getNalUnitType();
01214   int prevIRAPSubpicPOC = getPrevIRAPSubpicPOC();
01215 
01216   if (getCtuAddrInSlice(0) == getPPS()->getSubPic(curSubpicIdx).getFirstCTUInSubPic())
01217   {
01218     // subpicture type related constraints invoked only if the current slice is the first slice of a subpicture
01219     int prevGDRSubpicPOC = getPrevGDRSubpicPOC();
01220     int prevIRAPSubpicType = getPrevIRAPSubpicType();
01221 
01222     if (prevIRAPSubpicPOC > getPOC() && (nalUnitType < NAL_UNIT_CODED_SLICE_IDR_W_RADL || nalUnitType > NAL_UNIT_CODED_SLICE_CRA))
01223     {
01224       CHECK(nalUnitType != NAL_UNIT_CODED_SLICE_RASL && nalUnitType != NAL_UNIT_CODED_SLICE_RADL,
01225         "When a subpicture is a leading subpicture of an IRAP subpicture, it shall be a RADL or RASL subpicture");
01226     }
01227 
01228     if (prevIRAPSubpicPOC <= getPOC())
01229     {
01230       CHECK(nalUnitType == NAL_UNIT_CODED_SLICE_RASL || nalUnitType == NAL_UNIT_CODED_SLICE_RADL,
01231         "When a subpicture is not a leading subpicture of an IRAP subpicture, it shall not be a RADL or RASL subpicture");
01232     }
01233 
01234     CHECK(nalUnitType == NAL_UNIT_CODED_SLICE_RASL && (prevIRAPSubpicType == NAL_UNIT_CODED_SLICE_IDR_N_LP || prevIRAPSubpicType == NAL_UNIT_CODED_SLICE_IDR_W_RADL),
01235       "No RASL subpictures shall be present in the bitstream that are associated with an IDR subpicture");
01236 
01237     CHECK(nalUnitType == NAL_UNIT_CODED_SLICE_RADL && prevIRAPSubpicType == NAL_UNIT_CODED_SLICE_IDR_N_LP,
01238       "No RADL subpictures shall be present in the bitstream that are associated with an IDR subpicture having nal_unit_type equal to IDR_N_LP");
01239 
01240     //constraints related to current subpicture type and its preceding subpicture types
01241     PicList::iterator iterPic = rcListPic.begin();
01242     int numNonLeadingPic = 0;
01243     while (iterPic != rcListPic.end())
01244     {
01245       Picture* bufPic = *(iterPic++);
01246       if (!bufPic->reconstructed)
01247       {
01248         continue;
01249       }
01250       if (bufPic->poc == getPOC())
01251       {
01252         continue;
01253       }
01254 
01255       //identify the subpicture in the reference picture buffer that with nuh_layer_id equal to current subpicture layerId and subpicture index equal to current subpicIdx
01256       bool isBufPicOutput = false;
01257       int bufSubpicType = NAL_UNIT_INVALID;
01258       int bufSubpicPrevIRAPSubpicPOC = 0;
01259       for (int i = 0; i < bufPic->numSlices; i++)
01260       {
01261         if (bufPic->sliceSubpicIdx[i] == curSubpicIdx)
01262         {
01263           isBufPicOutput = bufPic->slices[i]->getPicHeader()->getPicOutputFlag();
01264           bufSubpicType = bufPic->slices[i]->getNalUnitType();
01265           bufSubpicPrevIRAPSubpicPOC = bufPic->slices[i]->getPrevIRAPSubpicPOC();
01266           break;
01267         }
01268       }
01269 
01270       if ((nalUnitType == NAL_UNIT_CODED_SLICE_CRA || nalUnitType == NAL_UNIT_CODED_SLICE_IDR_N_LP || nalUnitType == NAL_UNIT_CODED_SLICE_IDR_W_RADL) &&
01271         !this->getNoOutputOfPriorPicsFlag() && isBufPicOutput == 1 && bufPic->layerId == m_nuhLayerId)
01272       {
01273         CHECK(bufPic->poc >= getPOC(), "Any subpicture, with nuh_layer_id equal to a particular value layerId and subpicture index equal to a particular value subpicIdx, that "
01274           "precedes, in decoding order, an IRAP subpicture with nuh_layer_id equal to layerId and subpicture index equal to subpicIdx shall precede, in output order, the "
01275           "IRAP subpicture");
01276       }
01277 
01278       if (nalUnitType == NAL_UNIT_CODED_SLICE_RADL && isBufPicOutput == 1 && bufPic->layerId == m_nuhLayerId &&
01279         prevIRAPSubpicPOC > bufSubpicPrevIRAPSubpicPOC && prevIRAPSubpicPOC != bufPic->poc)
01280       {
01281         CHECK(bufPic->poc >= getPOC(), "Any subpicture, with nuh_layer_id equal to a particular value layerId and subpicture index equal to a particular value subpicIdx, that "
01282           "precedes, in decoding order, an IRAP subpicture with nuh_layer_id equal to layerId and subpicture index equal to subpicIdx shall precede, in output order, all "
01283           "its associated RADL subpictures");
01284       }
01285 
01286       if ((getPOC() == getPicHeader()->getRecoveryPocCnt() + prevGDRSubpicPOC) && !this->getNoOutputOfPriorPicsFlag() && isBufPicOutput == 1 &&
01287         bufPic->layerId == m_nuhLayerId && nalUnitType != NAL_UNIT_CODED_SLICE_GDR && getPicHeader()->getRecoveryPocCnt() != -1)
01288       {
01289         CHECK(bufPic->poc >= getPOC(), "Any subpicture, with nuh_layer_id equal to a particular value layerId and subpicture index equal to a particular value subpicIdx, that "
01290           "precedes, in decoding order, a subpicture with nuh_layer_id equal to layerId and subpicture index equal to subpicIdx in a recovery point picture shall precede "
01291           "that subpicture in the recovery point picture in output order");
01292       }
01293 
01294       if (nalUnitType == NAL_UNIT_CODED_SLICE_RASL && prevIRAPSubpicType == NAL_UNIT_CODED_SLICE_CRA && bufSubpicType == NAL_UNIT_CODED_SLICE_RADL &&
01295         prevIRAPSubpicPOC == bufSubpicPrevIRAPSubpicPOC)
01296       {
01297         CHECK(bufPic->poc <= getPOC(), "Any RASL subpicture associated with a CRA subpicture shall precede any RADL subpicture associated with the CRA subpicture in output order");
01298       }
01299 
01300       if (nalUnitType == NAL_UNIT_CODED_SLICE_RASL && prevIRAPSubpicType == NAL_UNIT_CODED_SLICE_CRA && bufPic->layerId == m_nuhLayerId && bufPic->poc < prevIRAPSubpicPOC)
01301       {
01302         if (bufSubpicType == NAL_UNIT_CODED_SLICE_IDR_N_LP || bufSubpicType == NAL_UNIT_CODED_SLICE_IDR_W_RADL ||
01303           bufSubpicType == NAL_UNIT_CODED_SLICE_CRA || bufSubpicType == NAL_UNIT_CODED_SLICE_GDR)
01304         {
01305           CHECK(bufPic->poc >= getPOC(), "Any RASL subpicture, with nuh_layer_id equal to a particular value layerId and subpicture index equal to a particular value subpicIdx, "
01306             "associated with a CRA subpicture shall follow, in output order, any IRAP or GDR subpicture , with nuh_layer_id equal to layerId and subpicture index equal to "
01307             "subpicIdx, that precedes the CRA subpicture in decoding order");
01308         }
01309       }
01310 
01311       if ((nalUnitType == NAL_UNIT_CODED_SLICE_RASL || nalUnitType == NAL_UNIT_CODED_SLICE_RADL) &&
01312         bufSubpicType != NAL_UNIT_CODED_SLICE_RASL && bufSubpicType != NAL_UNIT_CODED_SLICE_RADL &&
01313         bufSubpicPrevIRAPSubpicPOC == prevIRAPSubpicPOC && bufPic->layerId == m_nuhLayerId)
01314       {
01315         numNonLeadingPic++;
01316         int th = bufPic->cs->sps->getFieldSeqFlag() ? 1 : 0;
01317         CHECK(bufPic->poc > prevIRAPSubpicPOC && numNonLeadingPic > th, "If sps_field_seq_flag is equal to 0 and the current subpicture, with nuh_layer_id equal to a particular value "
01318           "layerId and subpicture index equal to a particular value subpicIdx, is a leading subpicture associated with an IRAP subpicture, it shall precede, in decoding order, "
01319           "all non-leading subpictures that are associated with the same IRAP subpicture. Otherwise, let subpicA and subpicB be the first and the last leading subpictures, in "
01320           "decoding order, associated with an IRAP subpicture, respectively, there shall be at most one non-leading subpicture with nuh_layer_id equal to layerId and subpicture "
01321           "index equal to subpicIdx preceding subpicA in decoding order, and there shall be no non-leading picture with nuh_layer_id equal to layerId and subpicture index equal "
01322           "to subpicIdx between picA and picB in decoding order");
01323       }
01324     }
01325   }
01326 
01327   //subpic RPL related constraints
01328   Picture* pcRefPic;
01329   int refPicPOC;
01330   int refPicDecodingOrderNumber;
01331 
01332   int numEntriesL0 = pRPL0->getNumberOfShorttermPictures() + pRPL0->getNumberOfLongtermPictures() + pRPL0->getNumberOfInterLayerPictures();
01333   int numEntriesL1 = pRPL1->getNumberOfShorttermPictures() + pRPL1->getNumberOfLongtermPictures() + pRPL1->getNumberOfInterLayerPictures();
01334 
01335   int numActiveEntriesL0 = getNumRefIdx(REF_PIC_LIST_0);
01336   int numActiveEntriesL1 = getNumRefIdx(REF_PIC_LIST_1);
01337 
01338   int layerIdx = m_pcPic->cs->vps == nullptr ? 0 : m_pcPic->cs->vps->getGeneralLayerIdx(m_pcPic->layerId);
01339   for (int i = 0; i < numEntriesL0; i++)
01340   {
01341     if (pRPL0->isInterLayerRefPic(i))
01342     {
01343       int refLayerId = m_pcPic->cs->vps->getLayerId(m_pcPic->cs->vps->getDirectRefLayerIdx(layerIdx, pRPL0->getInterLayerRefPicIdx(i)));
01344       pcRefPic = xGetRefPic(rcListPic, getPOC(), refLayerId);
01345       refPicPOC = pcRefPic->getPOC();
01346     }
01347     else if (!pRPL0->isRefPicLongterm(i))
01348     {
01349       refPicPOC = getPOC() + pRPL0->getRefPicIdentifier(i);
01350       pcRefPic = xGetRefPic(rcListPic, refPicPOC, m_pcPic->layerId);
01351     }
01352     else
01353     {
01354       int pocBits = getSPS()->getBitsForPOC();
01355       int pocMask = (1 << pocBits) - 1;
01356       int ltrpPoc = pRPL0->getRefPicIdentifier(i) & pocMask;
01357       if(pRPL0->getDeltaPocMSBPresentFlag(i))
01358       {
01359         ltrpPoc += getPOC() - pRPL0->getDeltaPocMSBCycleLT(i) * (pocMask + 1) - (getPOC() & pocMask);
01360       }
01361       pcRefPic = xGetLongTermRefPic(rcListPic, ltrpPoc, pRPL0->getDeltaPocMSBPresentFlag(i), m_pcPic->layerId);
01362       refPicPOC = pcRefPic->getPOC();
01363     }
01364 
01365     if (pcRefPic) // the checks are for all reference picture, but we may not have an inactive reference picture, if starting with a CRA
01366     {
01367       refPicDecodingOrderNumber = pcRefPic->getDecodingOrderNumber();
01368 
01369       if (nalUnitType == NAL_UNIT_CODED_SLICE_CRA || nalUnitType == NAL_UNIT_CODED_SLICE_IDR_W_RADL || nalUnitType == NAL_UNIT_CODED_SLICE_IDR_N_LP)
01370       {
01371         CHECK(refPicPOC < prevIRAPSubpicPOC || refPicDecodingOrderNumber < prevIRAPSubpicDecOrderNo, "When the current subpicture, with nuh_layer_id equal to a particular value "
01372               "layerId and subpicture index equal to a particular value subpicIdx, is an IRAP subpicture, there shall be no picture referred to by an entry in RefPicList[0] that "
01373               "precedes, in output order or decoding order,any preceding picture, in decoding order (when present), containing an IRAP subpicture with nuh_layer_id equal to "
01374               "layerId and subpicture index equal to subpicIdx");
01375       }
01376 
01377       if (prevIRAPSubpicPOC < getPOC() && !getSPS()->getFieldSeqFlag())
01378       {
01379         CHECK(refPicPOC < prevIRAPSubpicPOC || refPicDecodingOrderNumber < prevIRAPSubpicDecOrderNo, "When the current subpicture follows an IRAP subpicture having the same value "
01380               "of nuh_layer_id and the same value of subpicture index in both decoding and output order, there shall be no picture referred to by an active entry in RefPicList[ 0 ] "
01381               "that precedes the picture containing that IRAP subpicture in output order or decoding order");
01382       }
01383 
01384       if (i < numActiveEntriesL0)
01385       {
01386         if (prevIRAPSubpicPOC < getPOC())
01387         {
01388           CHECK(refPicPOC < prevIRAPSubpicPOC || refPicDecodingOrderNumber < prevIRAPSubpicDecOrderNo, "When the current subpicture follows an IRAP subpicture having the same value "
01389                 "of nuh_layer_id and the same value of subpicture index and the leading subpictures, if any, associated with that IRAP subpicture in both decoding and output order, "
01390                 "there shall be no picture referred to by an entry in RefPicList[ 0 ] that precedes the picture containing that IRAP subpicture in output order or decoding order");
01391         }
01392 
01393         if (nalUnitType == NAL_UNIT_CODED_SLICE_RADL)
01394         {
01395           CHECK(refPicDecodingOrderNumber < prevIRAPSubpicDecOrderNo, "When the current subpicture, with nuh_layer_id equal to a particular value layerId and subpicture index equal "
01396                 "to a particular value subpicIdx, is a RADL subpicture, there shall be no active entry in RefPicList[ 0 ] that is a picture that precedes the picture containing the"
01397                 "associated IRAP subpicture in decoding order");
01398 
01399           if (pcRefPic->layerId == m_nuhLayerId)
01400           {
01401             for (int i = 0; i < pcRefPic->numSlices; i++)
01402             {
01403               if (pcRefPic->sliceSubpicIdx[i] == curSubpicIdx)
01404               {
01405                 CHECK(pcRefPic->slices[i]->getNalUnitType() == NAL_UNIT_CODED_SLICE_RASL, "When the current subpicture, with nuh_layer_id equal to a particular value layerId and "
01406                       "subpicture index equal to a particular value subpicIdx, is a RADL subpicture, there shall be no active entry in RefPicList[ 0 ] that is a picture with "
01407                       "nuh_layer_id equal to layerId containing a RASL subpicture with subpicture index equal to subpicIdx");
01408               }
01409             }
01410           }
01411         }
01412       }
01413     }
01414   }
01415 
01416   for (int i = 0; i < numEntriesL1; i++)
01417   {
01418     if (pRPL1->isInterLayerRefPic(i))
01419     {
01420       int refLayerId = m_pcPic->cs->vps->getLayerId(m_pcPic->cs->vps->getDirectRefLayerIdx(layerIdx, pRPL1->getInterLayerRefPicIdx(i)));
01421       pcRefPic = xGetRefPic(rcListPic, getPOC(), refLayerId);
01422       refPicPOC = pcRefPic->getPOC();
01423     }
01424     else if (!pRPL1->isRefPicLongterm(i))
01425     {
01426       refPicPOC = getPOC() + pRPL1->getRefPicIdentifier(i);
01427       pcRefPic = xGetRefPic(rcListPic, refPicPOC, m_pcPic->layerId);
01428     }
01429     else
01430     {
01431       int pocBits = getSPS()->getBitsForPOC();
01432       int pocMask = (1 << pocBits) - 1;
01433       int ltrpPoc = pRPL1->getRefPicIdentifier(i) & pocMask;
01434       if (pRPL1->getDeltaPocMSBPresentFlag(i))
01435       {
01436         ltrpPoc += getPOC() - pRPL1->getDeltaPocMSBCycleLT(i) * (pocMask + 1) - (getPOC() & pocMask);
01437       }
01438       pcRefPic = xGetLongTermRefPic(rcListPic, ltrpPoc, pRPL1->getDeltaPocMSBPresentFlag(i), m_pcPic->layerId);
01439       refPicPOC = pcRefPic->getPOC();
01440     }
01441     if (pcRefPic) // the checks are for all reference picture, but we may not have an inactive reference picture, if starting with a CRA
01442     {
01443       refPicDecodingOrderNumber = pcRefPic->getDecodingOrderNumber();
01444 
01445       if (nalUnitType == NAL_UNIT_CODED_SLICE_CRA || nalUnitType == NAL_UNIT_CODED_SLICE_IDR_W_RADL || nalUnitType == NAL_UNIT_CODED_SLICE_IDR_N_LP)
01446       {
01447         CHECK(refPicPOC < prevIRAPSubpicPOC || refPicDecodingOrderNumber < prevIRAPSubpicDecOrderNo, "When the current subpicture, with nuh_layer_id equal to a particular value"
01448               "layerId and subpicture index equal to a particular value subpicIdx, is an IRAP subpicture, there shall be no picture referred to by an entry in RefPicList[1] that"
01449               "precedes, in output order or decoding order,any preceding picture, in decoding order (when present), containing an IRAP subpicture with nuh_layer_id equal to "
01450               "layerId and subpicture index equal to subpicIdx");
01451       }
01452 
01453       if (prevIRAPSubpicPOC < getPOC() && !getSPS()->getFieldSeqFlag())
01454       {
01455         CHECK(refPicPOC < prevIRAPSubpicPOC || refPicDecodingOrderNumber < prevIRAPSubpicDecOrderNo, "When the current subpicture follows an IRAP subpicture having the same value "
01456               "of nuh_layer_id and the same value of subpicture index in both decoding and output order, there shall be no picture referred to by an active entry in RefPicList[ 1 ] "
01457               "that precedes the picture containing that IRAP subpicture in output order or decoding order");
01458       }
01459       if (i < numActiveEntriesL1)
01460       {
01461         if (prevIRAPSubpicPOC < getPOC())
01462         {
01463           CHECK(refPicPOC < prevIRAPSubpicPOC || refPicDecodingOrderNumber < prevIRAPSubpicDecOrderNo, "When the current subpicture follows an IRAP subpicture having the same value "
01464                 "of nuh_layer_id and the same value of subpicture index and the leading subpictures, if any, associated with that IRAP subpicture in both decoding and output order, "
01465                 "there shall be no picture referred to by an entry in RefPicList[ 1 ] that precedes the picture containing that IRAP subpicture in output order or decoding order");
01466         }
01467 
01468         if (nalUnitType == NAL_UNIT_CODED_SLICE_RADL)
01469         {
01470           CHECK(refPicDecodingOrderNumber < prevIRAPSubpicDecOrderNo, "When the current subpicture, with nuh_layer_id equal to a particular value layerId and subpicture index equal "
01471                 "to a particular value subpicIdx, is a RADL subpicture, there shall be no active entry in RefPicList[ 1 ] that is a picture that precedes the picture containing the"
01472                 "associated IRAP subpicture in decoding order");
01473 
01474           if (pcRefPic->layerId == m_nuhLayerId)
01475           {
01476             for (int i = 0; i < pcRefPic->numSlices; i++)
01477             {
01478               if (pcRefPic->sliceSubpicIdx[i] == curSubpicIdx)
01479               {
01480                 CHECK(pcRefPic->slices[i]->getNalUnitType() == NAL_UNIT_CODED_SLICE_RASL, "When the current subpicture, with nuh_layer_id equal to a particular value layerId and "
01481                       "subpicture index equal to a particular value subpicIdx, is a RADL subpicture, there shall be no active entry in RefPicList[ 1 ] that is a picture with "
01482                       "nuh_layer_id equal to layerId containing a RASL subpicture with subpicture index equal to subpicIdx");
01483               }
01484             }
01485           }
01486         }
01487       }
01488     }
01489   }
01490 }
