01493 //Function for applying picture marking based on the Reference Picture List
01494 void Slice::applyReferencePictureListBasedMarking( PicList& rcListPic, const ReferencePictureList *pRPL0, const ReferencePictureList *pRPL1, const int layerId, const PPS& pps ) const
01495 {
01496   int i, isReference;
01497   checkLeadingPictureRestrictions(rcListPic, pps);
01498 
01499   bool isNeedToCheck = (this->getNalUnitType() == NAL_UNIT_CODED_SLICE_IDR_N_LP || this->getNalUnitType() == NAL_UNIT_CODED_SLICE_IDR_W_RADL) ? false : true;
01500 
01501   // mark long-term reference pictures in List0
01502   for( i = 0; i < pRPL0->getNumberOfShorttermPictures() + pRPL0->getNumberOfLongtermPictures() + pRPL0->getNumberOfInterLayerPictures(); i++ )
01503   {
01504     if( !pRPL0->isRefPicLongterm( i ) || pRPL0->isInterLayerRefPic( i ) )
01505     {
01506       continue;
01507     }
01508 
01509     int isAvailable = 0;
01510     PicList::iterator iterPic = rcListPic.begin();
01511     while (iterPic != rcListPic.end())
01512     {
01513       Picture* rpcPic = *(iterPic++);
01514       if (!rpcPic->referenced)
01515       {
01516         continue;
01517       }
01518       int pocCycle = 1 << (rpcPic->cs->sps->getBitsForPOC());
01519       int curPoc = rpcPic->getPOC();
01520       int refPoc = pRPL0->getRefPicIdentifier(i) & (pocCycle - 1);
01521       if(pRPL0->getDeltaPocMSBPresentFlag(i))
01522       {
01523         refPoc += getPOC() - pRPL0->getDeltaPocMSBCycleLT(i) * pocCycle - (getPOC() & (pocCycle - 1));
01524       }
01525       else
01526       {
01527         curPoc = curPoc & (pocCycle - 1);
01528       }
01529       if (rpcPic->longTerm && curPoc == refPoc && rpcPic->referenced)
01530       {
01531         isAvailable = 1;
01532         break;
01533       }
01534     }
01535     // if there was no such long-term check the short terms
01536     if (!isAvailable)
01537     {
01538       iterPic = rcListPic.begin();
01539       while (iterPic != rcListPic.end())
01540       {
01541         Picture* rpcPic = *(iterPic++);
01542         if (!rpcPic->referenced)
01543         {
01544           continue;
01545         }
01546         int pocCycle = 1 << (rpcPic->cs->sps->getBitsForPOC());
01547         int curPoc = rpcPic->getPOC();
01548         int refPoc = pRPL0->getRefPicIdentifier(i) & (pocCycle - 1);
01549         if(pRPL0->getDeltaPocMSBPresentFlag(i))
01550         {
01551           refPoc += getPOC() - pRPL0->getDeltaPocMSBCycleLT(i) * pocCycle - (getPOC() & (pocCycle - 1));
01552         }
01553         else
01554         {
01555           curPoc = curPoc & (pocCycle - 1);
01556         }
01557         if (!rpcPic->longTerm && curPoc == refPoc && rpcPic->referenced)
01558         {
01559           isAvailable = 1;
01560           rpcPic->longTerm = true;
01561           break;
01562         }
01563       }
01564     }
01565   }
01566 
01567   // mark long-term reference pictures in List1
01568   for( i = 0; i < pRPL1->getNumberOfShorttermPictures() + pRPL1->getNumberOfLongtermPictures() + pRPL1->getNumberOfInterLayerPictures(); i++ )
01569   {
01570     if( !pRPL1->isRefPicLongterm( i ) || pRPL1->isInterLayerRefPic( i ) )
01571     {
01572       continue;
01573     }
01574 
01575     int isAvailable = 0;
01576     PicList::iterator iterPic = rcListPic.begin();
01577     while (iterPic != rcListPic.end())
01578     {
01579       Picture* rpcPic = *(iterPic++);
01580       if (!rpcPic->referenced)
01581       {
01582         continue;
01583       }
01584       int pocCycle = 1 << (rpcPic->cs->sps->getBitsForPOC());
01585       int curPoc = rpcPic->getPOC();
01586       int refPoc = pRPL1->getRefPicIdentifier(i) & (pocCycle - 1);
01587       if(pRPL1->getDeltaPocMSBPresentFlag(i))
01588       {
01589         refPoc += getPOC() - pRPL1->getDeltaPocMSBCycleLT(i) * pocCycle - (getPOC() & (pocCycle - 1));
01590       }
01591       else
01592       {
01593         curPoc = curPoc & (pocCycle - 1);
01594       }
01595       if (rpcPic->longTerm && curPoc == refPoc && rpcPic->referenced)
01596       {
01597         isAvailable = 1;
01598         break;
01599       }
01600     }
01601     // if there was no such long-term check the short terms
01602     if (!isAvailable)
01603     {
01604       iterPic = rcListPic.begin();
01605       while (iterPic != rcListPic.end())
01606       {
01607         Picture* rpcPic = *(iterPic++);
01608         if (!rpcPic->referenced)
01609         {
01610           continue;
01611         }
01612         int pocCycle = 1 << (rpcPic->cs->sps->getBitsForPOC());
01613         int curPoc = rpcPic->getPOC();
01614         int refPoc = pRPL1->getRefPicIdentifier(i) & (pocCycle - 1);
01615         if(pRPL1->getDeltaPocMSBPresentFlag(i))
01616         {
01617           refPoc += getPOC() - pRPL1->getDeltaPocMSBCycleLT(i) * pocCycle - (getPOC() & (pocCycle - 1));
01618         }
01619         else
01620         {
01621           curPoc = curPoc & (pocCycle - 1);
01622         }
01623         if (!rpcPic->longTerm && curPoc == refPoc && rpcPic->referenced)
01624         {
01625           isAvailable = 1;
01626           rpcPic->longTerm = true;
01627           break;
01628         }
01629       }
01630     }
01631   }
01632 
01633   // loop through all pictures in the reference picture buffer
01634   PicList::iterator iterPic = rcListPic.begin();
01635   while (iterPic != rcListPic.end())
01636   {
01637     Picture* pcPic = *(iterPic++);
01638 
01639     if (!pcPic->referenced)
01640       continue;
01641 
01642     isReference = 0;
01643     // loop through all pictures in the Reference Picture Set
01644     // to see if the picture should be kept as reference picture
01645     for( i = 0; isNeedToCheck && !isReference && i < pRPL0->getNumberOfShorttermPictures() + pRPL0->getNumberOfLongtermPictures() + pRPL0->getNumberOfInterLayerPictures(); i++ )
01646     {
01647       if( pRPL0->isInterLayerRefPic( i ) )
01648       {
01649         // Diagonal inter-layer prediction is not allowed
01650         CHECK( pRPL0->getRefPicIdentifier( i ), "ILRP identifier should be 0" );
01651 
01652         if( pcPic->poc == m_iPOC )
01653         {
01654           isReference = 1;
01655           pcPic->longTerm = true;
01656         }
01657       }
01658       else if (pcPic->layerId == layerId)
01659       {
01660       if (!(pRPL0->isRefPicLongterm(i)))
01661       {
01662         if (pcPic->poc == this->getPOC() + pRPL0->getRefPicIdentifier(i))
01663         {
01664           isReference = 1;
01665           pcPic->longTerm = false;
01666         }
01667       }
01668       else
01669       {
01670         int pocCycle = 1 << (pcPic->cs->sps->getBitsForPOC());
01671         int curPoc = pcPic->poc;
01672         int refPoc = pRPL0->getRefPicIdentifier(i) & (pocCycle - 1);
01673         if(pRPL0->getDeltaPocMSBPresentFlag(i))
01674         {
01675           refPoc += getPOC() - pRPL0->getDeltaPocMSBCycleLT(i) * pocCycle - (getPOC() & (pocCycle - 1));
01676         }
01677         else
01678         {
01679           curPoc = curPoc & (pocCycle - 1);
01680         }
01681         if (pcPic->longTerm && curPoc == refPoc)
01682         {
01683           isReference = 1;
01684           pcPic->longTerm = true;
01685         }
01686       }
01687       }
01688     }
01689 
01690     for( i = 0; isNeedToCheck && !isReference && i < pRPL1->getNumberOfShorttermPictures() + pRPL1->getNumberOfLongtermPictures() + pRPL1->getNumberOfInterLayerPictures(); i++ )
01691     {
01692       if( pRPL1->isInterLayerRefPic( i ) )
01693       {
01694         // Diagonal inter-layer prediction is not allowed
01695         CHECK( pRPL1->getRefPicIdentifier( i ), "ILRP identifier should be 0" );
01696 
01697         if( pcPic->poc == m_iPOC )
01698         {
01699           isReference = 1;
01700           pcPic->longTerm = true;
01701         }
01702       }
01703       else if( pcPic->layerId == layerId )
01704       {
01705       if (!(pRPL1->isRefPicLongterm(i)))
01706       {
01707         if (pcPic->poc == this->getPOC() + pRPL1->getRefPicIdentifier(i))
01708         {
01709           isReference = 1;
01710           pcPic->longTerm = false;
01711         }
01712       }
01713       else
01714       {
01715         int pocCycle = 1 << (pcPic->cs->sps->getBitsForPOC());
01716         int curPoc = pcPic->poc;
01717         int refPoc = pRPL1->getRefPicIdentifier(i) & (pocCycle - 1);
01718         if(pRPL1->getDeltaPocMSBPresentFlag(i))
01719         {
01720           refPoc += getPOC() - pRPL1->getDeltaPocMSBCycleLT(i) * pocCycle - (getPOC() & (pocCycle - 1));
01721         }
01722         else
01723         {
01724           curPoc = curPoc & (pocCycle - 1);
01725         }
01726         if (pcPic->longTerm && curPoc == refPoc)
01727         {
01728           isReference = 1;
01729           pcPic->longTerm = true;
01730         }
01731       }
01732       }
01733     }
01734     // mark the picture as "unused for reference" if it is not in
01735     // the Reference Picture List
01736     if( pcPic->layerId == layerId && pcPic->poc != m_iPOC && isReference == 0 )
01737     {
01738       pcPic->referenced = false;
01739       pcPic->longTerm = false;
01740     }
01741 
01742     // sanity checks
01743     if (pcPic->referenced)
01744     {
01745       //check that pictures of higher temporal layers are not used
01746       CHECK(pcPic->usedByCurr && !(pcPic->temporalId <= this->getTLayer()), "Invalid state");
01747     }
01748   }
01749 }
