01751 int Slice::checkThatAllRefPicsAreAvailable(PicList& rcListPic, const ReferencePictureList *pRPL, int rplIdx, bool printErrors) const
01752 {
01753   Picture* rpcPic;
01754   int isAvailable = 0;
01755   int notPresentPoc = 0;
01756 
01757   if (this->isIDRorBLA()) return 0; //Assume that all pic in the DPB will be flushed anyway so no need to check.
01758 
01759   int numberOfPictures = pRPL->getNumberOfLongtermPictures() + pRPL->getNumberOfShorttermPictures() + pRPL->getNumberOfInterLayerPictures();
01760   //Check long term ref pics
01761   for (int ii = 0; pRPL->getNumberOfLongtermPictures() > 0 && ii < numberOfPictures; ii++)
01762   {
01763     if( !pRPL->isRefPicLongterm( ii ) || pRPL->isInterLayerRefPic( ii ) )
01764     {
01765       continue;
01766     }
01767 
01768     notPresentPoc = pRPL->getRefPicIdentifier(ii);
01769     isAvailable = 0;
01770     PicList::iterator iterPic = rcListPic.begin();
01771     while (iterPic != rcListPic.end())
01772     {
01773       rpcPic = *(iterPic++);
01774       int pocCycle = 1 << (rpcPic->cs->sps->getBitsForPOC());
01775       int curPoc = rpcPic->getPOC();
01776       int refPoc = pRPL->getRefPicIdentifier(ii) & (pocCycle - 1);
01777       if(pRPL->getDeltaPocMSBPresentFlag(ii))
01778       {
01779         refPoc += getPOC() - pRPL->getDeltaPocMSBCycleLT(ii) * pocCycle - (getPOC() & (pocCycle - 1));
01780       }
01781       else
01782       {
01783         curPoc = curPoc & (pocCycle - 1);
01784       }
01785       if (rpcPic->longTerm && curPoc == refPoc && rpcPic->referenced)
01786       {
01787         isAvailable = 1;
01788         break;
01789       }
01790     }
01791     // if there was no such long-term check the short terms
01792     if (!isAvailable)
01793     {
01794       iterPic = rcListPic.begin();
01795       while (iterPic != rcListPic.end())
01796       {
01797         rpcPic = *(iterPic++);
01798         int pocCycle = 1 << (rpcPic->cs->sps->getBitsForPOC());
01799         int curPoc = rpcPic->getPOC();
01800         int refPoc = pRPL->getRefPicIdentifier(ii) & (pocCycle - 1);
01801         if(pRPL->getDeltaPocMSBPresentFlag(ii))
01802         {
01803           refPoc += getPOC() - pRPL->getDeltaPocMSBCycleLT(ii) * pocCycle - (getPOC() & (pocCycle - 1));
01804         }
01805         else
01806         {
01807           curPoc = curPoc & (pocCycle - 1);
01808         }
01809         if (!rpcPic->longTerm && curPoc == refPoc && rpcPic->referenced)
01810         {
01811           isAvailable = 1;
01812           rpcPic->longTerm = true;
01813           break;
01814         }
01815       }
01816     }
01817     if (!isAvailable)
01818     {
01819       if (printErrors)
01820       {
01821         msg(ERROR, "\nCurrent picture: %d Long-term reference picture with POC = %3d seems to have been removed or not correctly decoded.", this->getPOC(), notPresentPoc);
01822       }
01823       return notPresentPoc;
01824     }
01825   }
01826   //report that a picture is lost if it is in the Reference Picture List but not in the DPB
01827 
01828   isAvailable = 0;
01829   //Check short term ref pics
01830   for (int ii = 0; ii < numberOfPictures; ii++)
01831   {
01832     if (pRPL->isRefPicLongterm(ii))
01833       continue;
01834 
01835     notPresentPoc = this->getPOC() + pRPL->getRefPicIdentifier(ii);
01836     isAvailable = 0;
01837     PicList::iterator iterPic = rcListPic.begin();
01838     while (iterPic != rcListPic.end())
01839     {
01840       rpcPic = *(iterPic++);
01841       if (!rpcPic->longTerm && rpcPic->getPOC() == this->getPOC() + pRPL->getRefPicIdentifier(ii) && rpcPic->referenced)
01842       {
01843         isAvailable = 1;
01844         break;
01845       }
01846     }
01847     //report that a picture is lost if it is in the Reference Picture List but not in the DPB
01848     if (isAvailable == 0 && pRPL->getNumberOfShorttermPictures() > 0)
01849     {
01850       if (printErrors)
01851       {
01852         msg(ERROR, "\nCurrent picture: %d Short-term reference picture with POC = %3d seems to have been removed or not correctly decoded.", this->getPOC(), notPresentPoc);
01853       }
01854       return notPresentPoc;
01855     }
01856   }
01857   return 0;
01858 }
