01891       else
01892       {
01893         curPoc = curPoc & (pocCycle - 1);
01894       }
01895       if (rpcPic->longTerm && curPoc == refPoc && rpcPic->referenced)
01896       {
01897         isAvailable = 1;
01898         break;
01899       }
01900     }
01901     // if there was no such long-term check the short terms
01902     if (!isAvailable)
01903     {
01904       iterPic = rcListPic.begin();
01905       while (iterPic != rcListPic.end())
01906       {
01907         rpcPic = *(iterPic++);
01908         int pocCycle = 1 << (rpcPic->cs->sps->getBitsForPOC());
01909         int curPoc = rpcPic->getPOC();
01910         int refPoc = pRPL->getRefPicIdentifier(ii) & (pocCycle - 1);
01911         if(pRPL->getDeltaPocMSBPresentFlag(ii))
01912         {
01913           refPoc += getPOC() - pRPL->getDeltaPocMSBCycleLT(ii) * pocCycle - (getPOC() & (pocCycle - 1));
01914         }
01915         else
01916         {
01917           curPoc = curPoc & (pocCycle - 1);
01918         }
01919         if (!rpcPic->longTerm && curPoc == refPoc && rpcPic->referenced)
01920         {
01921           isAvailable = 1;
01922           rpcPic->longTerm = true;
01923           break;
01924         }
01925       }
01926     }
01927     if (!isAvailable)
01928     {
01929       if (printErrors)
01930       {
01931         msg(ERROR, "\nCurrent picture: %d Long-term reference picture with POC = %3d seems to have been removed or not correctly decoded.", this->getPOC(), notPresentPoc);
01932       }
01933       *refPicIndex = ii;
01934       return notPresentPoc;
01935     }
01936   }
01937   //report that a picture is lost if it is in the Reference Picture List but not in the DPB
01938 
01939   isAvailable = 0;
01940   //Check short term ref pics
01941   for (int ii = 0; ii < numberOfPictures; ii++)
01942   {
01943     if (pRPL->isRefPicLongterm(ii))
01944       continue;
01945 
01946     notPresentPoc = this->getPOC() + pRPL->getRefPicIdentifier(ii);
01947     isAvailable = 0;
01948     PicList::iterator iterPic = rcListPic.begin();
01949     while (iterPic != rcListPic.end())
01950     {
01951       rpcPic = *(iterPic++);
01952       if (!rpcPic->longTerm && rpcPic->getPOC() == this->getPOC() + pRPL->getRefPicIdentifier(ii) && rpcPic->referenced)
01953       {
01954         isAvailable = 1;
01955         break;
01956       }
01957     }
01958     //report that a picture is lost if it is in the Reference Picture List but not in the DPB
01959     if (isAvailable == 0 && pRPL->getNumberOfShorttermPictures() > 0)
01960     {
01961       if (printErrors)
01962       {
01963         msg(ERROR, "\nCurrent picture: %d Short-term reference picture with POC = %3d seems to have been removed or not correctly decoded.", this->getPOC(), notPresentPoc);
01964       }
01965       *refPicIndex = ii;
01966       return notPresentPoc;
01967     }
01968   }
01969   return 0;
01970 }
01971 
01972 bool Slice::isPOCInRefPicList(const ReferencePictureList *rpl, int poc )
01973 {
01974   for( int i = 0; i < rpl->getNumberOfLongtermPictures() + rpl->getNumberOfShorttermPictures() + rpl->getNumberOfInterLayerPictures(); i++ )
01975   {
01976     if( rpl->isInterLayerRefPic( i ) )
01977     {
01978       // Diagonal inter-layer prediction is not allowed
01979       CHECK( rpl->getRefPicIdentifier( i ), "ILRP identifier should be 0" );
01980 
01981       if( poc == m_iPOC )
01982       {
01983         return true;
01984       }
01985     }
01986     else
01987     if (rpl->isRefPicLongterm(i))
01988     {
01989       if (poc == rpl->getRefPicIdentifier(i))
01990       {
01991         return true;
01992       }
01993     }
01994     else
01995     {
01996       if (poc == getPOC() + rpl->getRefPicIdentifier(i))
01997       {
01998         return true;
01999       }
02000     }
02001   }
02002   return false;
02003 }
02004 
02005 bool Slice::isPocRestrictedByDRAP( int poc, bool precedingDRAPInDecodingOrder )
02006 {
02007   if (!getEnableDRAPSEI())
02008   {
02009     return false;
02010   }
02011   return ( isDRAP() && poc != getAssociatedIRAPPOC() ) ||
02012          ( cvsHasPreviousDRAP() && getPOC() > getLatestDRAPPOC() && (precedingDRAPInDecodingOrder || poc < getLatestDRAPPOC()) );
02013 }
02014 
02015 void Slice::checkConformanceForDRAP( uint32_t temporalId )
02016 {
02017   if (!(isDRAP() || cvsHasPreviousDRAP()))
02018   {
02019     return;
02020   }
02021 
02022   if (isDRAP())
02023   {
02024     if (!(getNalUnitType() == NalUnitType::NAL_UNIT_CODED_SLICE_TRAIL ||
02025           getNalUnitType() == NalUnitType::NAL_UNIT_CODED_SLICE_STSA))
02026     {
02027       msg( WARNING, "Warning, non-conforming bitstream. The DRAP picture should be a trailing picture.\n");
02028     }
02029     if ( temporalId != 0)
02030     {
02031       msg( WARNING, "Warning, non-conforming bitstream. The DRAP picture shall have a temporal sublayer identifier equal to 0.\n");
02032     }
02033     for (int i = 0; i < getNumRefIdx(REF_PIC_LIST_0); i++)
02034     {
02035       if (getRefPic(REF_PIC_LIST_0,i)->getPOC() != getAssociatedIRAPPOC())
02036       {
02037         msg( WARNING, "Warning, non-conforming bitstream. The DRAP picture shall not include any pictures in the active "
02038                       "entries of its reference picture lists except the preceding IRAP picture in decoding order.\n");
02039       }
02040     }
02041     for (int i = 0; i < getNumRefIdx(REF_PIC_LIST_1); i++)
02042     {
02043       if (getRefPic(REF_PIC_LIST_1,i)->getPOC() != getAssociatedIRAPPOC())
02044       {
02045         msg( WARNING, "Warning, non-conforming bitstream. The DRAP picture shall not include any pictures in the active "
02046                       "entries of its reference picture lists except the preceding IRAP picture in decoding order.\n");
02047       }
02048     }
02049   }
02050 
02051   if (cvsHasPreviousDRAP() && getPOC() > getLatestDRAPPOC())
02052   {
02053     for (int i = 0; i < getNumRefIdx(REF_PIC_LIST_0); i++)
02054     {
02055       if (getRefPic(REF_PIC_LIST_0,i)->getPOC() < getLatestDRAPPOC() && getRefPic(REF_PIC_LIST_0,i)->getPOC() != getAssociatedIRAPPOC())
02056       {
02057         msg( WARNING, "Warning, non-conforming bitstream. Any picture that follows the DRAP picture in both decoding order "
02058                     "and output order shall not include, in the active entries of its reference picture lists, any picture "
02059                     "that precedes the DRAP picture in decoding order or output order, with the exception of the preceding "
02060                     "IRAP picture in decoding order. Problem is POC %d in RPL0.\n", getRefPic(REF_PIC_LIST_0,i)->getPOC());
02061       }
02062     }
02063     for (int i = 0; i < getNumRefIdx(REF_PIC_LIST_1); i++)
02064     {
02065       if (getRefPic(REF_PIC_LIST_1,i)->getPOC() < getLatestDRAPPOC() && getRefPic(REF_PIC_LIST_1,i)->getPOC() != getAssociatedIRAPPOC())
02066       {
02067         msg( WARNING, "Warning, non-conforming bitstream. Any picture that follows the DRAP picture in both decoding order "
02068                     "and output order shall not include, in the active entries of its reference picture lists, any picture "
02069                     "that precedes the DRAP picture in decoding order or output order, with the exception of the preceding "
02070                     "IRAP picture in decoding order. Problem is POC %d in RPL1", getRefPic(REF_PIC_LIST_1,i)->getPOC());
02071       }
02072     }
02073   }
02074 }
