02121 void  Slice::resetWpScaling()
02122 {
02123   for ( int e=0 ; e<NUM_REF_PIC_LIST_01 ; e++ )
02124   {
02125     for ( int i=0 ; i<MAX_NUM_REF ; i++ )
02126     {
02127       for ( int yuv=0 ; yuv<MAX_NUM_COMPONENT ; yuv++ )
02128       {
02129         WPScalingParam  *pwp = &(m_weightPredTable[e][i][yuv]);
02130         pwp->presentFlag     = false;
02131         pwp->log2WeightDenom = 0;
02132         pwp->log2WeightDenom = 0;
02133         pwp->codedWeight     = 1;
02134         pwp->codedOffset     = 0;
02135       }
02136     }
02137   }
02138 }
02139 
02141 void  Slice::initWpScaling(const SPS *sps)
02142 {
02143   const bool bUseHighPrecisionPredictionWeighting = sps->getSpsRangeExtension().getHighPrecisionOffsetsEnabledFlag();
02144   for ( int e=0 ; e<NUM_REF_PIC_LIST_01 ; e++ )
02145   {
02146     for ( int i=0 ; i<MAX_NUM_REF ; i++ )
02147     {
02148       for ( int yuv=0 ; yuv<MAX_NUM_COMPONENT ; yuv++ )
02149       {
02150         WPScalingParam  *pwp = &(m_weightPredTable[e][i][yuv]);
02151         if (!pwp->presentFlag)
02152         {
02153           // Inferring values not present :
02154           pwp->codedWeight = (1 << pwp->log2WeightDenom);
02155           pwp->codedOffset = 0;
02156         }
02157 
02158         const int offsetScalingFactor = bUseHighPrecisionPredictionWeighting ? 1 : (1 << (sps->getBitDepth(toChannelType(ComponentID(yuv)))-8));
02159 
02160         pwp->w = pwp->codedWeight;
02161         pwp->o = pwp->codedOffset * offsetScalingFactor;   // NOTE: This value of the ".o" variable is never used - .o
02162                                                            // is set immediately before it gets used
02163         pwp->shift = pwp->log2WeightDenom;
02164         pwp->round = (pwp->log2WeightDenom >= 1) ? (1 << (pwp->log2WeightDenom - 1)) : (0);
02165       }
02166     }
02167   }
02168 }
