02182 unsigned Slice::getMinPictureDistance() const
02183 {
02184   int minPicDist = MAX_INT;
02185   if (getSPS()->getIBCFlag())
02186   {
02187     minPicDist = 0;
02188   }
02189   else
02190   if( ! isIntra() )
02191   {
02192     const int currPOC  = getPOC();
02193     for (int refIdx = 0; refIdx < getNumRefIdx(REF_PIC_LIST_0); refIdx++)
02194     {
02195       minPicDist = std::min( minPicDist, std::abs(currPOC - getRefPic(REF_PIC_LIST_0, refIdx)->getPOC()));
02196     }
02197     if( getSliceType() == B_SLICE )
02198     {
02199       for (int refIdx = 0; refIdx < getNumRefIdx(REF_PIC_LIST_1); refIdx++)
02200       {
02201         minPicDist = std::min(minPicDist, std::abs(currPOC - getRefPic(REF_PIC_LIST_1, refIdx)->getPOC()));
02202       }
02203     }
02204   }
02205   return (unsigned) minPicDist;
02206 }
