02275 void VPS::deriveOutputLayerSets()
02276 {
02277   if( m_vpsEachLayerIsAnOlsFlag || m_vpsOlsModeIdc < 2 )
02278   {
02279     m_totalNumOLSs = m_maxLayers;
02280   }
02281   else if( m_vpsOlsModeIdc == 2 )
02282   {
02283     m_totalNumOLSs = m_vpsNumOutputLayerSets;
02284   }
02285 
02286   m_olsDpbParamsIdx.resize( m_totalNumOLSs );
02287   m_olsDpbPicSize.resize( m_totalNumOLSs, Size(0, 0) );
02288   m_numOutputLayersInOls.resize( m_totalNumOLSs );
02289   m_numLayersInOls.resize( m_totalNumOLSs );
02290   m_outputLayerIdInOls.resize( m_totalNumOLSs, std::vector<int>( m_maxLayers, NOT_VALID ) );
02291   m_numSubLayersInLayerInOLS.resize( m_totalNumOLSs, std::vector<int>( m_maxLayers, NOT_VALID ) );
02292   m_layerIdInOls.resize( m_totalNumOLSs, std::vector<int>( m_maxLayers, NOT_VALID ) );
02293   m_olsDpbChromaFormatIdc.resize(m_totalNumOLSs);
02294   m_olsDpbBitDepthMinus8.resize(m_totalNumOLSs);
02295 
02296   std::vector<int> numRefLayers( m_maxLayers );
02297   std::vector<std::vector<int>> outputLayerIdx( m_totalNumOLSs, std::vector<int>( m_maxLayers, NOT_VALID ) );
02298   std::vector<std::vector<int>> layerIncludedInOlsFlag( m_totalNumOLSs, std::vector<int>( m_maxLayers, 0 ) );
02299   std::vector<std::vector<int>> dependencyFlag( m_maxLayers, std::vector<int>( m_maxLayers, NOT_VALID ) );
02300   std::vector<std::vector<int>> refLayerIdx( m_maxLayers, std::vector<int>( m_maxLayers, NOT_VALID ) );
02301   std::vector<int> layerUsedAsRefLayerFlag( m_maxLayers, 0 );
02302   std::vector<int> layerUsedAsOutputLayerFlag( m_maxLayers, NOT_VALID );
02303 
02304   for( int i = 0; i < m_maxLayers; i++ )
02305   {
02306     int r = 0;
02307 
02308     for( int j = 0; j < m_maxLayers; j++ )
02309     {
02310       dependencyFlag[i][j] = m_vpsDirectRefLayerFlag[i][j];
02311 
02312       for( int k = 0; k < i; k++ )
02313       {
02314         if( m_vpsDirectRefLayerFlag[i][k] && dependencyFlag[k][j] )
02315         {
02316           dependencyFlag[i][j] = 1;
02317         }
02318       }
02319       if (m_vpsDirectRefLayerFlag[i][j])
02320       {
02321         layerUsedAsRefLayerFlag[j] = 1;
02322       }
02323 
02324       if( dependencyFlag[i][j] )
02325       {
02326         refLayerIdx[i][r++] = j;
02327       }
02328     }
02329 
02330     numRefLayers[i] = r;
02331   }
02332 
02333   m_numOutputLayersInOls[0] = 1;
02334   m_outputLayerIdInOls[0][0] = m_vpsLayerId[0];
02335 #if JVET_R0193_S0141
02336   m_numSubLayersInLayerInOLS[0][0] = m_ptlMaxTemporalId[m_olsPtlIdx[0]] + 1;
02337 #else
02338   m_numSubLayersInLayerInOLS[0][0] = m_vpsMaxSubLayers;
02339 #endif
02340   layerUsedAsOutputLayerFlag[0] = 1;
02341   for (int i = 1; i < m_maxLayers; i++)
02342   {
02343     if (m_vpsEachLayerIsAnOlsFlag || m_vpsOlsModeIdc < 2)
02344     {
02345       layerUsedAsOutputLayerFlag[i] = 1;
02346     }
02347     else
02348     {
02349       layerUsedAsOutputLayerFlag[i] = 0;
02350     }
02351   }
02352   for( int i = 1; i < m_totalNumOLSs; i++ )
02353   {
02354     if( m_vpsEachLayerIsAnOlsFlag || m_vpsOlsModeIdc == 0 )
02355     {
02356       m_numOutputLayersInOls[i] = 1;
02357       m_outputLayerIdInOls[i][0] = m_vpsLayerId[i];
02358 #if JVET_R0193_S0141
02359       if (m_vpsEachLayerIsAnOlsFlag)
02360       {
02361         m_numSubLayersInLayerInOLS[i][0] = m_ptlMaxTemporalId[m_olsPtlIdx[i]] + 1;
02362       }
02363       else
02364       {
02365         m_numSubLayersInLayerInOLS[i][i] = m_ptlMaxTemporalId[m_olsPtlIdx[i]] + 1;
02366         for (int k = i - 1; k >= 0; k--)
02367         {
02368           m_numSubLayersInLayerInOLS[i][k] = 0;
02369           for (int m = k + 1; m <= i; m++)
02370           {
02371             uint32_t maxSublayerNeeded = std::min((uint32_t)m_numSubLayersInLayerInOLS[i][m], m_vpsMaxTidIlRefPicsPlus1[m][k]);
02372             if (m_vpsDirectRefLayerFlag[m][k] && m_numSubLayersInLayerInOLS[i][k] < maxSublayerNeeded)
02373             {
02374               m_numSubLayersInLayerInOLS[i][k] = maxSublayerNeeded;
02375             }
02376           }
02377       }
02378       }
02379 #else
02380       for(int  j = 0; j < i  &&  ( m_vpsOlsModeIdc  ==  0 ); j++ )
02381       {
02382         m_numSubLayersInLayerInOLS[i][j] = m_vpsMaxTidIlRefPicsPlus1[i];
02383       }
02384       m_numSubLayersInLayerInOLS[i][i] = m_vpsMaxSubLayers;
02385 #endif
02386     }
02387     else if( m_vpsOlsModeIdc == 1 )
02388     {
02389       m_numOutputLayersInOls[i] = i + 1;
02390 
02391       for( int j = 0; j < m_numOutputLayersInOls[i]; j++ )
02392       {
02393         m_outputLayerIdInOls[i][j] = m_vpsLayerId[j];
02394 #if JVET_R0193_S0141
02395         m_numSubLayersInLayerInOLS[i][j] = m_ptlMaxTemporalId[m_olsPtlIdx[i]] + 1;
02396 #else
02397         m_numSubLayersInLayerInOLS[i][j] = m_vpsMaxSubLayers;
02398 #endif
02399       }
02400     }
02401     else if( m_vpsOlsModeIdc == 2 )
02402     {
02403       int j = 0;
02404 #if JVET_R0193
02405       int highestIncludedLayer = 0;
02406 #endif
02407       for( j = 0; j  <  m_maxLayers; j++ )
02408       {
02409         m_numSubLayersInLayerInOLS[i][j] = 0;
02410       }
02411       j = 0;
02412       for( int k = 0; k < m_maxLayers; k++ )
02413       {
02414         if( m_vpsOlsOutputLayerFlag[i][k] )
02415         {
02416           layerIncludedInOlsFlag[i][k] = 1;
02417 #if JVET_R0193
02418           highestIncludedLayer = k;
02419 #endif
02420           layerUsedAsOutputLayerFlag[k] = 1;
02421           outputLayerIdx[i][j] = k;
02422           m_outputLayerIdInOls[i][j++] = m_vpsLayerId[k];
02423 #if JVET_R0193_S0141
02424           m_numSubLayersInLayerInOLS[i][k] = m_ptlMaxTemporalId[m_olsPtlIdx[i]] + 1;
02425 #else
02426           m_numSubLayersInLayerInOLS[i][k] = m_vpsMaxSubLayers;
02427 #endif
02428         }
02429       }
02430       m_numOutputLayersInOls[i] = j;
02431 
02432       for( j = 0; j < m_numOutputLayersInOls[i]; j++ )
02433       {
02434         int idx = outputLayerIdx[i][j];
02435         for( int k = 0; k < numRefLayers[idx]; k++ )
02436         {
02437           layerIncludedInOlsFlag[i][refLayerIdx[idx][k]] = 1;
02438 #if !JVET_R0193
02439           if( m_numSubLayersInLayerInOLS[i][ refLayerIdx[idx][k] ] < m_vpsMaxTidIlRefPicsPlus1[ m_outputLayerIdInOls[i][j] ] )
02440           {
02441             m_numSubLayersInLayerInOLS[i][ refLayerIdx[idx][k] ] =  m_vpsMaxTidIlRefPicsPlus1[ m_outputLayerIdInOls[i][j] ];
02442           }
02443 #endif
02444         }
02445       }
02446 #if JVET_R0193
02447       for (int k = highestIncludedLayer - 1; k >= 0; k--)
02448       {
02449         if (layerIncludedInOlsFlag[i][k] && !m_vpsOlsOutputLayerFlag[i][k])
02450         {
02451           for (int m = k + 1; m <= highestIncludedLayer; m++)
02452           {
02453             uint32_t maxSublayerNeeded = std::min((uint32_t)m_numSubLayersInLayerInOLS[i][m], m_vpsMaxTidIlRefPicsPlus1[m][k]);
02454             if (m_vpsDirectRefLayerFlag[m][k] && layerIncludedInOlsFlag[i][m] && m_numSubLayersInLayerInOLS[i][k] < maxSublayerNeeded)
02455             {
02456               m_numSubLayersInLayerInOLS[i][k] = maxSublayerNeeded;
02457             }
02458           }
02459         }
02460       }
02461 #endif
02462     }
02463   }
02464   for (int i = 0; i < m_maxLayers; i++)
02465   {
02466     CHECK(layerUsedAsRefLayerFlag[i] == 0 && layerUsedAsOutputLayerFlag[i] == 0, "There shall be no layer that is neither an output layer nor a direct reference layer");
02467   }
02468 
02469   m_numLayersInOls[0] = 1;
02470   m_layerIdInOls[0][0] = m_vpsLayerId[0];
02471   m_numMultiLayeredOlss = 0;
02472   for( int i = 1; i < m_totalNumOLSs; i++ )
02473   {
02474     if( m_vpsEachLayerIsAnOlsFlag )
02475     {
02476       m_numLayersInOls[i] = 1;
02477       m_layerIdInOls[i][0] = m_vpsLayerId[i];
02478     }
02479     else if( m_vpsOlsModeIdc == 0 || m_vpsOlsModeIdc == 1 )
02480     {
02481       m_numLayersInOls[i] = i + 1;
02482       for( int j = 0; j < m_numLayersInOls[i]; j++ )
02483       {
02484         m_layerIdInOls[i][j] = m_vpsLayerId[j];
02485       }
02486     }
02487     else if( m_vpsOlsModeIdc == 2 )
02488     {
02489       int j = 0;
02490       for( int k = 0; k < m_maxLayers; k++ )
02491       {
02492         if( layerIncludedInOlsFlag[i][k] )
02493         {
02494           m_layerIdInOls[i][j++] = m_vpsLayerId[k];
02495         }
02496       }
02497 
02498       m_numLayersInOls[i] = j;
02499     }
02500     if( m_numLayersInOls[i] > 1 )
02501     {
02502       m_multiLayerOlsIdx[i] = m_numMultiLayeredOlss;
02503       m_numMultiLayeredOlss++;
02504     }
02505   }
02506   m_multiLayerOlsIdxToOlsIdx.resize(m_numMultiLayeredOlss);
02507 
02508   for (int i=0, j=0; i<m_totalNumOLSs; i++)
02509   {
02510     if (m_numLayersInOls[i] > 1)
02511     {
02512       m_multiLayerOlsIdxToOlsIdx[j] = i;
02513     }
02514   }
02515 }
02516 
02517 void VPS::checkVPS()
02518 {
02519   for (int multiLayerOlsIdx=0; multiLayerOlsIdx < m_numMultiLayeredOlss; multiLayerOlsIdx++)
02520   {
02521     const int olsIdx = m_multiLayerOlsIdxToOlsIdx[multiLayerOlsIdx];
02522     const int olsTimingHrdIdx = getOlsTimingHrdIdx(multiLayerOlsIdx);
02523     const int olsPtlIdx = getOlsPtlIdx(olsIdx);
02524     CHECK (getHrdMaxTid(olsTimingHrdIdx) < getPtlMaxTemporalId(olsPtlIdx), "The value of vps_hrd_max_tid[vps_ols_timing_hrd_idx[m]] shall be greater than or equal to "
02525                                                                      "vps_ptl_max_tid[ vps_ols_ptl_idx[n]] for each m-th multi-layer OLS for m from 0 to "
02526                                                                      "NumMultiLayerOlss - 1, inclusive, and n being the OLS index of the m-th multi-layer OLS among all OLSs.");
02527     const int olsDpbParamsIdx = getOlsDpbParamsIdx(multiLayerOlsIdx);
02528     CHECK (m_dpbMaxTemporalId[olsDpbParamsIdx] < getPtlMaxTemporalId(olsPtlIdx), "The value of vps_dpb_max_tid[vps_ols_dpb_params_idx[m]] shall be greater than or equal to "
02529                                                                      "vps_ptl_max_tid[ vps_ols_ptl_idx[n]] for each m-th multi-layer OLS for m from 0 to "
02530                                                                      "NumMultiLayerOlss - 1, inclusive, and n being the OLS index of the m-th multi-layer OLS among all OLSs.");
02531   }
02532 }
