02535 void VPS::deriveTargetOutputLayerSet( int targetOlsIdx )
02536 {
02537   m_targetOlsIdx = targetOlsIdx < 0 ? m_maxLayers - 1 : targetOlsIdx;
02538   m_targetOutputLayerIdSet.clear();
02539   m_targetLayerIdSet.clear();
02540 
02541   for( int i = 0; i < m_numOutputLayersInOls[m_targetOlsIdx]; i++ )
02542   {
02543     m_targetOutputLayerIdSet.push_back( m_outputLayerIdInOls[m_targetOlsIdx][i] );
02544   }
02545 
02546   for( int i = 0; i < m_numLayersInOls[m_targetOlsIdx]; i++ )
02547   {
02548     m_targetLayerIdSet.push_back( m_layerIdInOls[m_targetOlsIdx][i] );
02549   }
02550 }
