02552 #if JVET_S0163_ON_TARGETOLS_SUBLAYERS
02553 int VPS::deriveTargetOLSIdx(void)
02554 {
02555   int lowestIdx = 0;
02556   int highestNumLayers = m_numLayersInOls[lowestIdx];
02557 
02558   if ((m_numLayersInOls.size() > 1 ))
02559   {
02560     for (int idx = 1; idx < m_numLayersInOls.size(); idx++)
02561     {
02562       if(highestNumLayers == m_numLayersInOls[idx])
02563       {
02564         if (m_numOutputLayersInOls[lowestIdx] < m_numOutputLayersInOls[idx])
02565         {
02566           lowestIdx       = idx;
02567         }
02568       }
02569       else if(highestNumLayers < m_numLayersInOls[idx])
02570       {
02571         highestNumLayers = m_numLayersInOls[idx];
02572         lowestIdx       = idx;
02573       }
02574     }
02575   }
02576   return lowestIdx;
02577 }
