02965 {
02966   m_qpBdOffset = qpBdOffset;
02967   m_sameCQPTableForAllChromaFlag = params.m_sameCQPTableForAllChromaFlag;
02968   m_numQpTables = params.m_numQpTables;
02969 
02970   for (int i = 0; i < MAX_NUM_CQP_MAPPING_TABLES; i++)
02971   {
02972     m_numPtsInCQPTableMinus1[i] = params.m_numPtsInCQPTableMinus1[i];
02973     m_deltaQpInValMinus1[i] = params.m_deltaQpInValMinus1[i];
02974     m_qpTableStartMinus26[i] = params.m_qpTableStartMinus26[i];
02975     m_deltaQpOutVal[i] = params.m_deltaQpOutVal[i];
02976   }
02977 }
02978 void ChromaQpMappingTable::derivedChromaQPMappingTables()
02979 {
02980   for (int i = 0; i < getNumQpTables(); i++)
02981   {
02982     const int qpBdOffsetC = m_qpBdOffset;
02983     const int numPtsInCQPTableMinus1 = getNumPtsInCQPTableMinus1(i);
02984     std::vector<int> qpInVal(numPtsInCQPTableMinus1 + 2), qpOutVal(numPtsInCQPTableMinus1 + 2);
02985 
02986     qpInVal[0] = getQpTableStartMinus26(i) + 26;
02987     qpOutVal[0] = qpInVal[0];
02988     for (int j = 0; j <= getNumPtsInCQPTableMinus1(i); j++)
02989     {
02990       qpInVal[j + 1] = qpInVal[j] + getDeltaQpInValMinus1(i, j) + 1;
02991       qpOutVal[j + 1] = qpOutVal[j] + getDeltaQpOutVal(i, j);
02992     }
02993 
02994     for (int j = 0; j <= getNumPtsInCQPTableMinus1(i); j++)
02995     {
02996       CHECK(qpInVal[j]  < -qpBdOffsetC || qpInVal[j]  > MAX_QP, "qpInVal out of range");
02997       CHECK(qpOutVal[j] < -qpBdOffsetC || qpOutVal[j] > MAX_QP, "qpOutVal out of range");
02998     }
02999 
03000     m_chromaQpMappingTables[i][qpInVal[0]] = qpOutVal[0];
03001     for (int k = qpInVal[0] - 1; k >= -qpBdOffsetC; k--)
03002     {
03003       m_chromaQpMappingTables[i][k] = Clip3(-qpBdOffsetC, MAX_QP, m_chromaQpMappingTables[i][k + 1] - 1);
03004     }
03005     for (int j = 0; j <= numPtsInCQPTableMinus1; j++)
03006     {
03007       int sh = (getDeltaQpInValMinus1(i, j) + 1) >> 1;
03008       for (int k = qpInVal[j] + 1, m = 1; k <= qpInVal[j + 1]; k++, m++)
03009       {
03010         m_chromaQpMappingTables[i][k] = m_chromaQpMappingTables[i][qpInVal[j]]
03011           + ((qpOutVal[j + 1] - qpOutVal[j]) * m + sh) / (getDeltaQpInValMinus1(i, j) + 1);
03012       }
03013     }
03014     for (int k = qpInVal[numPtsInCQPTableMinus1 + 1] + 1; k <= MAX_QP; k++)
03015     {
03016       m_chromaQpMappingTables[i][k] = Clip3(-qpBdOffsetC, MAX_QP, m_chromaQpMappingTables[i][k - 1] + 1);
03017     }
03018   }
03019 }
