03177 void PPS::initTiles()
03178 {
03179   int       colIdx, rowIdx;
03180   int       ctuX, ctuY;
03181 
03182   // check explicit tile column sizes
03183   uint32_t  remainingWidthInCtu  = m_picWidthInCtu;
03184 
03185   for( colIdx = 0; colIdx < m_numExpTileCols; colIdx++ )
03186   {
03187     CHECK(m_tileColWidth[colIdx] > remainingWidthInCtu,    "Tile column width exceeds picture width");
03188     remainingWidthInCtu -= m_tileColWidth[colIdx];
03189   }
03190 
03191   // divide remaining picture width into uniform tile columns
03192   uint32_t  uniformTileColWidth = m_tileColWidth[colIdx-1];
03193   while( remainingWidthInCtu > 0 )
03194   {
03195     CHECK(colIdx >= MAX_TILE_COLS, "Number of tile columns exceeds valid range");
03196     uniformTileColWidth = std::min(remainingWidthInCtu, uniformTileColWidth);
03197     m_tileColWidth.push_back( uniformTileColWidth );
03198     remainingWidthInCtu -= uniformTileColWidth;
03199     colIdx++;
03200   }
03201   m_numTileCols = colIdx;
03202 
03203   // check explicit tile row sizes
03204   uint32_t  remainingHeightInCtu  = m_picHeightInCtu;
03205 
03206   for( rowIdx = 0; rowIdx < m_numExpTileRows; rowIdx++ )
03207   {
03208     CHECK(m_tileRowHeight[rowIdx] > remainingHeightInCtu,     "Tile row height exceeds picture height");
03209     remainingHeightInCtu -= m_tileRowHeight[rowIdx];
03210   }
03211 
03212   // divide remaining picture height into uniform tile rows
03213   uint32_t  uniformTileRowHeight = m_tileRowHeight[rowIdx - 1];
03214   while( remainingHeightInCtu > 0 )
03215   {
03216     uniformTileRowHeight = std::min(remainingHeightInCtu, uniformTileRowHeight);
03217     m_tileRowHeight.push_back( uniformTileRowHeight );
03218     remainingHeightInCtu -= uniformTileRowHeight;
03219     rowIdx++;
03220   }
03221   m_numTileRows = rowIdx;
03222 
03223   // set left column bounaries
03224   m_tileColBd.push_back( 0 );
03225   for( colIdx = 0; colIdx < m_numTileCols; colIdx++ )
03226   {
03227     m_tileColBd.push_back( m_tileColBd[ colIdx ] + m_tileColWidth[ colIdx ] );
03228   }
03229 
03230   // set top row bounaries
03231   m_tileRowBd.push_back( 0 );
03232   for( rowIdx = 0; rowIdx < m_numTileRows; rowIdx++ )
03233   {
03234     m_tileRowBd.push_back( m_tileRowBd[ rowIdx ] + m_tileRowHeight[ rowIdx ] );
03235   }
03236 
03237   // set mapping between horizontal CTU address and tile column index
03238   colIdx = 0;
03239   for( ctuX = 0; ctuX <= m_picWidthInCtu; ctuX++ )
03240   {
03241     if( ctuX == m_tileColBd[ colIdx + 1 ] )
03242     {
03243       colIdx++;
03244     }
03245     m_ctuToTileCol.push_back( colIdx );
03246   }
03247 
03248   // set mapping between vertical CTU address and tile row index
03249   rowIdx = 0;
03250   for( ctuY = 0; ctuY <= m_picHeightInCtu; ctuY++ )
03251   {
03252     if( ctuY == m_tileRowBd[ rowIdx + 1 ] )
03253     {
03254       rowIdx++;
03255     }
03256     m_ctuToTileRow.push_back( rowIdx );
03257   }
03258 }
