03268 
03272 void PPS::initRectSliceMap(const SPS  *sps)
03273 {
03274   uint32_t  ctuY;
03275   uint32_t  tileX, tileY;
03276 
03277   if (sps)
03278   {
03279     m_ctuToSubPicIdx.resize(getPicWidthInCtu() * getPicHeightInCtu());
03280     if (sps->getNumSubPics() > 1)
03281     {
03282       for (int i = 0; i <= sps->getNumSubPics() - 1; i++)
03283       {
03284         for (int y = sps->getSubPicCtuTopLeftY(i); y < sps->getSubPicCtuTopLeftY(i) + sps->getSubPicHeight(i); y++)
03285         {
03286           for (int x = sps->getSubPicCtuTopLeftX(i); x < sps->getSubPicCtuTopLeftX(i) + sps->getSubPicWidth(i); x++)
03287           {
03288             m_ctuToSubPicIdx[ x+ y * getPicWidthInCtu()] = i;
03289           }
03290         }
03291       }
03292     }
03293     else
03294     {
03295       for (int i = 0; i < getPicWidthInCtu() * getPicHeightInCtu(); i++)
03296       {
03297         m_ctuToSubPicIdx[i] = 0;
03298       }
03299     }
03300   }
03301 
03302   if( getSingleSlicePerSubPicFlag() )
03303   {
03304     CHECK (sps==nullptr, "RectSliceMap can only be initialized for slice_per_sub_pic_flag with a valid SPS");
03305     m_numSlicesInPic = sps->getNumSubPics();
03306 
03307     // allocate new memory for slice list
03308     CHECK(m_numSlicesInPic > MAX_SLICES, "Number of slices in picture exceeds valid range");
03309     m_sliceMap.resize( m_numSlicesInPic );
03310 
03311     if (sps->getNumSubPics() > 1)
03312     {
03313       // Q2001 v15 equation 29
03314       std::vector<uint32_t> subpicWidthInTiles;
03315       std::vector<uint32_t> subpicHeightInTiles;
03316       std::vector<uint32_t> subpicHeightLessThanOneTileFlag;
03317       subpicWidthInTiles.resize(sps->getNumSubPics());
03318       subpicHeightInTiles.resize(sps->getNumSubPics());
03319       subpicHeightLessThanOneTileFlag.resize(sps->getNumSubPics());
03320       for (uint32_t i = 0; i <sps->getNumSubPics(); i++)
03321       {
03322         uint32_t leftX = sps->getSubPicCtuTopLeftX(i);
03323         uint32_t rightX = leftX + sps->getSubPicWidth(i) - 1;
03324         subpicWidthInTiles[i] = m_ctuToTileCol[rightX] + 1 - m_ctuToTileCol[leftX];
03325 
03326         uint32_t topY = sps->getSubPicCtuTopLeftY(i);
03327         uint32_t bottomY = topY + sps->getSubPicHeight(i) - 1;
03328         subpicHeightInTiles[i] = m_ctuToTileRow[bottomY] + 1 - m_ctuToTileRow[topY];
03329 
03330         if (subpicHeightInTiles[i] == 1 && sps->getSubPicHeight(i) < m_tileRowHeight[m_ctuToTileRow[topY]] )
03331         {
03332           subpicHeightLessThanOneTileFlag[i] = 1;
03333         }
03334         else
03335         {
03336           subpicHeightLessThanOneTileFlag[i] = 0;
03337         }
03338       }
03339 
03340       for( int i = 0; i < m_numSlicesInPic; i++ )
03341       {
03342         CHECK(m_numSlicesInPic != sps->getNumSubPics(), "in single slice per subpic mode, number of slice and subpic shall be equal");
03343         m_sliceMap[ i ].initSliceMap();
03344         if (subpicHeightLessThanOneTileFlag[i])
03345         {
03346           m_sliceMap[i].addCtusToSlice(sps->getSubPicCtuTopLeftX(i), sps->getSubPicCtuTopLeftX(i) + sps->getSubPicWidth(i),
03347                                        sps->getSubPicCtuTopLeftY(i), sps->getSubPicCtuTopLeftY(i) + sps->getSubPicHeight(i), m_picWidthInCtu);
03348         }
03349         else
03350         {
03351           tileX = m_ctuToTileCol[sps->getSubPicCtuTopLeftX(i)];
03352           tileY = m_ctuToTileRow[sps->getSubPicCtuTopLeftY(i)];
03353           for (uint32_t j = 0; j< subpicHeightInTiles[i]; j++)
03354           {
03355             for (uint32_t k = 0; k < subpicWidthInTiles[i]; k++)
03356             {
03357               m_sliceMap[i].addCtusToSlice(getTileColumnBd(tileX + k), getTileColumnBd(tileX + k + 1), getTileRowBd(tileY + j), getTileRowBd(tileY + j + 1), m_picWidthInCtu);
03358             }
03359           }
03360         }
03361       }
03362       subpicWidthInTiles.clear();
03363       subpicHeightInTiles.clear();
03364       subpicHeightLessThanOneTileFlag.clear();
03365     }
03366     else
03367     {
03368       m_sliceMap[0].initSliceMap();
03369       for (int tileY=0; tileY<m_numTileRows; tileY++)
03370       {
03371         for (int tileX=0; tileX<m_numTileCols; tileX++)
03372         {
03373           m_sliceMap[0].addCtusToSlice(getTileColumnBd(tileX), getTileColumnBd(tileX + 1),
03374                                        getTileRowBd(tileY), getTileRowBd(tileY + 1), m_picWidthInCtu);
03375         }
03376       }
03377       m_sliceMap[0].setSliceID(0);
03378     }
03379   }
03380   else
03381   {
03382     // allocate new memory for slice list
03383     CHECK(m_numSlicesInPic > MAX_SLICES, "Number of slices in picture exceeds valid range");
03384     m_sliceMap.resize( m_numSlicesInPic );
03385     // generate CTU maps for all rectangular slices in picture
03386     for( uint32_t i = 0; i < m_numSlicesInPic; i++ )
03387     {
03388       m_sliceMap[ i ].initSliceMap();
03389 
03390       // get position of first tile in slice
03391       tileX =  m_rectSlices[ i ].getTileIdx() % m_numTileCols;
03392       tileY =  m_rectSlices[ i ].getTileIdx() / m_numTileCols;
03393 
03394       // infer slice size for last slice in picture
03395       if( i == m_numSlicesInPic-1 )
03396       {
03397         m_rectSlices[ i ].setSliceWidthInTiles ( m_numTileCols - tileX );
03398         m_rectSlices[ i ].setSliceHeightInTiles( m_numTileRows - tileY );
03399         m_rectSlices[ i ].setNumSlicesInTile( 1 );
03400       }
03401 
03402       // set slice index
03403       m_sliceMap[ i ].setSliceID(i);
03404 
03405       // complete tiles within a single slice case
03406       if( m_rectSlices[ i ].getSliceWidthInTiles( ) > 1 || m_rectSlices[ i ].getSliceHeightInTiles( ) > 1)
03407       {
03408         for( uint32_t j = 0; j < m_rectSlices[ i ].getSliceHeightInTiles( ); j++ )
03409         {
03410           for( uint32_t k = 0; k < m_rectSlices[ i ].getSliceWidthInTiles( ); k++ )
03411           {
03412             m_sliceMap[ i ].addCtusToSlice( getTileColumnBd(tileX + k), getTileColumnBd(tileX + k +1),
03413                                             getTileRowBd(tileY + j), getTileRowBd(tileY + j +1), m_picWidthInCtu);
03414           }
03415         }
03416       }
03417       // multiple slices within a single tile case
03418       else
03419       {
03420         uint32_t  numSlicesInTile = m_rectSlices[ i ].getNumSlicesInTile( );
03421 
03422         ctuY = getTileRowBd( tileY );
03423         for( uint32_t j = 0; j < numSlicesInTile-1; j++ )
03424         {
03425           m_sliceMap[ i ].addCtusToSlice( getTileColumnBd(tileX), getTileColumnBd(tileX+1),
03426                                           ctuY, ctuY + m_rectSlices[ i ].getSliceHeightInCtu(), m_picWidthInCtu);
03427           ctuY += m_rectSlices[ i ].getSliceHeightInCtu();
03428           i++;
03429           m_sliceMap[ i ].initSliceMap();
03430           m_sliceMap[ i ].setSliceID(i);
03431         }
03432 
03433         // infer slice height for last slice in tile
03434         CHECK( ctuY >= getTileRowBd( tileY + 1 ), "Invalid rectangular slice signalling");
03435         m_rectSlices[ i ].setSliceHeightInCtu( getTileRowBd( tileY + 1 ) - ctuY );
03436         m_sliceMap[ i ].addCtusToSlice( getTileColumnBd(tileX), getTileColumnBd(tileX+1),
03437                                         ctuY, getTileRowBd( tileY + 1 ), m_picWidthInCtu);
03438       }
03439     }
03440   }
03441   // check for valid rectangular slice map
03442   checkSliceMap();
03443 }
03444 
03448 void PPS::initSubPic(const SPS &sps)
03449 {
03450   if (getSubPicIdMappingInPpsFlag())
03451   {
03452     // When signalled, the number of subpictures has to match in PPS and SPS
03453     CHECK (getNumSubPics() != sps.getNumSubPics(), "pps_num_subpics_minus1 shall be equal to sps_num_subpics_minus1");
03454   }
03455   else
03456   {
03457     // When not signalled  set the numer equal for convenient access
03458     setNumSubPics(sps.getNumSubPics());
03459   }
03460 
03461   CHECK(getNumSubPics() > MAX_NUM_SUB_PICS, "Number of sub-pictures in picture exceeds valid range");
03462   m_subPics.resize(getNumSubPics());
03463 
03464   // Check that no subpicture is specified outside of the conformance cropping window
03465   for(int i = 0; i < sps.getNumSubPics(); i++)
03466   {
03467     CHECK( (sps.getSubPicCtuTopLeftX(i) * sps.getCTUSize()) >=
03468           (sps.getMaxPicWidthInLumaSamples() - sps.getConformanceWindow().getWindowRightOffset() * SPS::getWinUnitX(sps.getChromaFormatIdc())),
03469           "No subpicture can be located completely outside of the conformance cropping window");
03470     CHECK( ((sps.getSubPicCtuTopLeftX(i) + sps.getSubPicWidth(i)) * sps.getCTUSize()) <= (sps.getConformanceWindow().getWindowLeftOffset() * SPS::getWinUnitX(sps.getChromaFormatIdc())),
03471           "No subpicture can be located completely outside of the conformance cropping window" );
03472     CHECK( (sps.getSubPicCtuTopLeftY(i) * sps.getCTUSize()) >=
03473           (sps.getMaxPicHeightInLumaSamples()  - sps.getConformanceWindow().getWindowBottomOffset() * SPS::getWinUnitY(sps.getChromaFormatIdc())),
03474           "No subpicture can be located completely outside of the conformance cropping window");
03475     CHECK( ((sps.getSubPicCtuTopLeftY(i) + sps.getSubPicHeight(i)) * sps.getCTUSize()) <= (sps.getConformanceWindow().getWindowTopOffset() * SPS::getWinUnitY(sps.getChromaFormatIdc())),
03476           "No subpicture can be located completely outside of the conformance cropping window");
03477   }
03478 
03479   // m_ctuSize,  m_picWidthInCtu, and m_picHeightInCtu might not be initialized yet.
03480   if (m_ctuSize == 0 || m_picWidthInCtu == 0 || m_picHeightInCtu == 0)
03481   {
03482     m_ctuSize = sps.getCTUSize();
03483     m_picWidthInCtu = (m_picWidthInLumaSamples + m_ctuSize - 1) / m_ctuSize;
03484     m_picHeightInCtu = (m_picHeightInLumaSamples + m_ctuSize - 1) / m_ctuSize;
03485   }
03486   for (int i=0; i< getNumSubPics(); i++)
03487   {
03488     m_subPics[i].setSubPicIdx(i);
03489     if(sps.getSubPicIdMappingExplicitlySignalledFlag())
03490     {
03491       if(m_subPicIdMappingInPpsFlag)
03492       {
03493         m_subPics[i].setSubPicID(m_subPicId[i]);
03494       }
03495       else
03496       {
03497         m_subPics[i].setSubPicID(sps.getSubPicId(i));
03498       }
03499     }
03500     else
03501     {
03502       m_subPics[i].setSubPicID(i);
03503     }
03504     m_subPics[i].setSubPicCtuTopLeftX(sps.getSubPicCtuTopLeftX(i));
03505     m_subPics[i].setSubPicCtuTopLeftY(sps.getSubPicCtuTopLeftY(i));
03506     m_subPics[i].setSubPicWidthInCTUs(sps.getSubPicWidth(i));
03507     m_subPics[i].setSubPicHeightInCTUs(sps.getSubPicHeight(i));
03508 
03509     uint32_t firstCTU = sps.getSubPicCtuTopLeftY(i) * m_picWidthInCtu + sps.getSubPicCtuTopLeftX(i);    
03510     m_subPics[i].setFirstCTUInSubPic(firstCTU);
03511     uint32_t lastCTU = (sps.getSubPicCtuTopLeftY(i) + sps.getSubPicHeight(i) - 1) * m_picWidthInCtu + sps.getSubPicCtuTopLeftX(i) + sps.getSubPicWidth(i) - 1;
03512     m_subPics[i].setLastCTUInSubPic(lastCTU);
03513 
03514     uint32_t left = sps.getSubPicCtuTopLeftX(i) * m_ctuSize;
03515     m_subPics[i].setSubPicLeft(left);
03516 
03517     uint32_t right = std::min(m_picWidthInLumaSamples - 1, (sps.getSubPicCtuTopLeftX(i) + sps.getSubPicWidth(i)) * m_ctuSize - 1);
03518     m_subPics[i].setSubPicRight(right);
03519 
03520     m_subPics[i].setSubPicWidthInLumaSample(right - left + 1);
03521 
03522     uint32_t top = sps.getSubPicCtuTopLeftY(i) * m_ctuSize;
03523     m_subPics[i].setSubPicTop(top);
03524 
03525     uint32_t bottom = std::min(m_picHeightInLumaSamples - 1, (sps.getSubPicCtuTopLeftY(i) + sps.getSubPicHeight(i)) * m_ctuSize - 1);
03526 
03527     m_subPics[i].setSubPicHeightInLumaSample(bottom - top + 1);
03528 
03529     m_subPics[i].setSubPicBottom(bottom);
03530 
03531     m_subPics[i].clearCTUAddrList();
03532 
03533     if (m_numSlicesInPic == 1)
03534     {
03535       CHECK(getNumSubPics() != 1, "only one slice in picture, but number of subpic is not one");
03536       m_subPics[i].addAllCtusInPicToSubPic(0, getPicWidthInCtu(), 0, getPicHeightInCtu(), getPicWidthInCtu());
03537       m_subPics[i].setNumSlicesInSubPic(1);
03538     }
03539     else
03540     {
03541       int numSlicesInSubPic = 0;
03542       int idxLastSliceInSubpic = -1;
03543       int idxFirstSliceAfterSubpic = m_numSlicesInPic;
03544       for (int j = 0; j < m_numSlicesInPic; j++)
03545       {
03546         uint32_t ctu = m_sliceMap[j].getCtuAddrInSlice(0);
03547         uint32_t ctu_x = ctu % m_picWidthInCtu;
03548         uint32_t ctu_y = ctu / m_picWidthInCtu;
03549         if (ctu_x >= sps.getSubPicCtuTopLeftX(i) &&
03550           ctu_x < (sps.getSubPicCtuTopLeftX(i) + sps.getSubPicWidth(i)) &&
03551           ctu_y >= sps.getSubPicCtuTopLeftY(i) &&
03552           ctu_y < (sps.getSubPicCtuTopLeftY(i) + sps.getSubPicHeight(i)))
03553         {
03554           // add ctus in a slice to the subpicture it belongs to
03555           m_subPics[i].addCTUsToSubPic(m_sliceMap[j].getCtuAddrList());
03556       numSlicesInSubPic++;
03557           idxLastSliceInSubpic = j;
03558         }
03559         else if (idxFirstSliceAfterSubpic == m_numSlicesInPic && idxLastSliceInSubpic != -1)
03560         {
03561           idxFirstSliceAfterSubpic = j;
03562         }
03563       }
03564       CHECK( idxFirstSliceAfterSubpic < idxLastSliceInSubpic, "The signalling order of slices shall follow the coding order" );
03565       m_subPics[i].setNumSlicesInSubPic(numSlicesInSubPic);
03566     }
03567     m_subPics[i].setTreatedAsPicFlag(sps.getSubPicTreatedAsPicFlag(i));
03568     m_subPics[i].setloopFilterAcrossEnabledFlag(sps.getLoopFilterAcrossSubpicEnabledFlag(i));
03569   }
03570 }
