03602 void PPS::initRasterSliceMap( std::vector<uint32_t> numTilesInSlice )
03603 {
03604   uint32_t tileIdx = 0;
03605   setNumSlicesInPic( (uint32_t) numTilesInSlice.size() );
03606 
03607   // allocate new memory for slice list
03608   CHECK(m_numSlicesInPic > MAX_SLICES, "Number of slices in picture exceeds valid range");
03609   m_sliceMap.resize( m_numSlicesInPic );
03610 
03611   for( uint32_t sliceIdx = 0; sliceIdx < numTilesInSlice.size(); sliceIdx++ )
03612   {
03613     m_sliceMap[sliceIdx].initSliceMap();
03614     m_sliceMap[sliceIdx].setSliceID( tileIdx );
03615     m_sliceMap[sliceIdx].setNumTilesInSlice( numTilesInSlice[sliceIdx] );
03616     for( uint32_t idx = 0; idx < numTilesInSlice[sliceIdx]; idx++ )
03617     {
03618       uint32_t tileX = tileIdx % getNumTileColumns();
03619       uint32_t tileY = tileIdx / getNumTileColumns();
03620       CHECK(tileY >= getNumTileRows(), "Number of tiles in slice exceeds the remaining number of tiles in picture");
03621 
03622       m_sliceMap[sliceIdx].addCtusToSlice(getTileColumnBd(tileX), getTileColumnBd(tileX + 1),
03623                                           getTileRowBd(tileY), getTileRowBd(tileY + 1),
03624                                           getPicWidthInCtu());
03625       tileIdx++;
03626     }
03627   }
03628 
03629   // check for valid raster-scan slice map
03630   checkSliceMap();
03631 }
03632 
03636 void PPS::checkSliceMap()
03637 {
03638   uint32_t i;
03639   std::vector<uint32_t>  ctuList, sliceList;
03640   uint32_t picSizeInCtu = getPicWidthInCtu() * getPicHeightInCtu();
03641   for( i = 0; i < m_numSlicesInPic; i++ )
03642   {
03643     sliceList = m_sliceMap[ i ].getCtuAddrList();
03644     ctuList.insert( ctuList.end(), sliceList.begin(), sliceList.end() );
03645   }
03646   CHECK( ctuList.size() < picSizeInCtu, "Slice map contains too few CTUs");
03647   CHECK( ctuList.size() > picSizeInCtu, "Slice map contains too many CTUs");
03648   std::sort( ctuList.begin(), ctuList.end() );
03649   for( i = 1; i < ctuList.size(); i++ )
03650   {
03651     CHECK( ctuList[i] > ctuList[i-1]+1, "CTU missing in slice map");
03652     CHECK( ctuList[i] == ctuList[i-1],  "CTU duplicated in slice map");
03653   }
03654 }
