03800       }
03801     }
03802     else
03803     {
03804       if ((::memcmp(getScalingListAddress(scalingListId), getScalingListDefaultAddress(scalingListId), sizeof(int) * MAX_MATRIX_COEF_NUM)) || (getScalingListDC(scalingListId) != 16))
03805       {
03806         isAllDefault = false;
03807         break;
03808       }
03809     }
03810     if (!isAllDefault) break;
03811   }
03812 
03813   return !isAllDefault;
03814 }
