03821 int ScalingList::lengthUvlc(int uiCode)
03822 {
03823   if (uiCode < 0) printf("Error UVLC! \n");
03824 
03825   int uiLength = 1;
03826   int uiTemp = ++uiCode;
03827 
03828   CHECK(!uiTemp, "Integer overflow");
03829 
03830   while (1 != uiTemp)
03831   {
03832     uiTemp >>= 1;
03833     uiLength += 2;
03834   }
03835   return (uiLength >> 1) + ((uiLength + 1) >> 1);
03836 }
03837 int ScalingList::lengthSvlc(int uiCode)
03838 {
03839   uint32_t uiCode2 = uint32_t(uiCode <= 0 ? (-uiCode) << 1 : (uiCode << 1) - 1);
03840   int uiLength = 1;
03841   int uiTemp = ++uiCode2;
03842 
03843   CHECK(!uiTemp, "Integer overflow");
03844 
03845   while (1 != uiTemp)
03846   {
03847     uiTemp >>= 1;
03848     uiLength += 2;
03849   }
03850   return (uiLength >> 1) + ((uiLength + 1) >> 1);
03851 }
03852 void ScalingList::codePredScalingList(int* scalingList, const int* scalingListPred, int scalingListDC, int scalingListPredDC, int scalingListId, int& bitsCost) //sizeId, listId is current to-be-coded matrix idx
03853 {
03854   int deltaValue = 0;
03855   int matrixSize = (scalingListId < SCALING_LIST_1D_START_4x4) ? 2 : (scalingListId < SCALING_LIST_1D_START_8x8) ? 4 : 8;
03856   int coefNum = matrixSize*matrixSize;
03857   ScanElement *scan = g_scanOrder[SCAN_UNGROUPED][SCAN_DIAG][gp_sizeIdxInfo->idxFrom(matrixSize)][gp_sizeIdxInfo->idxFrom(matrixSize)];
03858   int nextCoef = 0;
03859 
03860   int8_t data;
03861   const int *src = scalingList;
03862   const int *srcPred = scalingListPred;
03863   if (scalingListDC!=-1 && scalingListPredDC!=-1)
03864   {
03865     bitsCost += lengthSvlc((int8_t)(scalingListDC - scalingListPredDC - nextCoef));
03866     nextCoef =  scalingListDC - scalingListPredDC;
03867   }
03868   else if ((scalingListDC != -1 && scalingListPredDC == -1))
03869   {
03870     bitsCost += lengthSvlc((int8_t)(scalingListDC - srcPred[scan[0].idx] - nextCoef));
03871     nextCoef =  scalingListDC - srcPred[scan[0].idx];
03872   }
03873   else if ((scalingListDC == -1 && scalingListPredDC == -1))
03874   {
03875   }
03876   else
03877   {
03878     printf("Predictor DC mismatch! \n");
03879   }
03880   for (int i = 0; i < coefNum; i++)
03881   {
03882     if (scalingListId >= SCALING_LIST_1D_START_64x64 && scan[i].x >= 4 && scan[i].y >= 4)
03883       continue;
03884     deltaValue = (src[scan[i].idx] - srcPred[scan[i].idx]);
03885     data = (int8_t)(deltaValue - nextCoef);
03886     nextCoef = deltaValue;
03887 
03888     bitsCost += lengthSvlc(data);
03889   }
03890 }
03891 void ScalingList::codeScalingList(int* scalingList, int scalingListDC, int scalingListId, int& bitsCost) //sizeId, listId is current to-be-coded matrix idx
03892 {
03893   int matrixSize = (scalingListId < SCALING_LIST_1D_START_4x4) ? 2 : (scalingListId < SCALING_LIST_1D_START_8x8) ? 4 : 8;
03894   int coefNum = matrixSize * matrixSize;
03895   ScanElement *scan = g_scanOrder[SCAN_UNGROUPED][SCAN_DIAG][gp_sizeIdxInfo->idxFrom(matrixSize)][gp_sizeIdxInfo->idxFrom(matrixSize)];
03896   int nextCoef = SCALING_LIST_START_VALUE;
03897   int8_t data;
03898   const int *src = scalingList;
03899 
03900   if (scalingListId >= SCALING_LIST_1D_START_16x16)
03901   {
03902     bitsCost += lengthSvlc(int8_t(getScalingListDC(scalingListId) - nextCoef));
03903     nextCoef = getScalingListDC(scalingListId);
03904   }
03905 
03906   for (int i = 0; i < coefNum; i++)
03907   {
03908     if (scalingListId >= SCALING_LIST_1D_START_64x64 && scan[i].x >= 4 && scan[i].y >= 4)
03909       continue;
03910     data = int8_t(src[scan[i].idx] - nextCoef);
03911     nextCoef = src[scan[i].idx];
03912 
03913     bitsCost += lengthSvlc(data);
03914   }
03915 }
03916 void ScalingList::CheckBestPredScalingList(int scalingListId, int predListId, int& BitsCount)
03917 {
03918   //check previously coded matrix as a predictor, code "lengthUvlc" function
03919   int *scalingList = getScalingListAddress(scalingListId);
03920   const int *scalingListPred = (scalingListId == predListId) ? ((predListId < SCALING_LIST_1D_START_8x8) ? g_quantTSDefault4x4 : g_quantIntraDefault8x8) : getScalingListAddress(predListId);
03921   int scalingListDC = (scalingListId >= SCALING_LIST_1D_START_16x16) ? getScalingListDC(scalingListId) : -1;
03922   int scalingListPredDC = (predListId >= SCALING_LIST_1D_START_16x16) ? ((scalingListId == predListId) ? 16 : getScalingListDC(predListId)) : -1;
03923 
03924   int bitsCost = 0;
03925   int matrixSize = (scalingListId < SCALING_LIST_1D_START_4x4) ? 2 : (scalingListId < SCALING_LIST_1D_START_8x8) ? 4 : 8;
03926   int predMatrixSize = (predListId < SCALING_LIST_1D_START_4x4) ? 2 : (predListId < SCALING_LIST_1D_START_8x8) ? 4 : 8;
03927 
03928   if (matrixSize != predMatrixSize) printf("Predictor size mismatch! \n");
03929 
03930   bitsCost = 2 + lengthUvlc(scalingListId - predListId);
03931   //copy-flag + predictor-mode-flag + deltaListId
03932   codePredScalingList(scalingList, scalingListPred, scalingListDC, scalingListPredDC, scalingListId, bitsCost);
03933   BitsCount = bitsCost;
03934 }
03935 void ScalingList::processRefMatrix(uint32_t scalinListId, uint32_t refListId)
03936 {
03937   int matrixSize = (scalinListId < SCALING_LIST_1D_START_4x4) ? 2 : (scalinListId < SCALING_LIST_1D_START_8x8) ? 4 : 8;
03938   ::memcpy(getScalingListAddress(scalinListId), ((scalinListId == refListId) ? getScalingListDefaultAddress(refListId) : getScalingListAddress(refListId)), sizeof(int)*matrixSize*matrixSize);
03939 }
03940 void ScalingList::checkPredMode(uint32_t scalingListId)
03941 {
03942   int bestBitsCount = MAX_INT;
03943   int BitsCount = 2;
03944   setScalingListPreditorModeFlag(scalingListId, false);
03945   codeScalingList(getScalingListAddress(scalingListId), ((scalingListId >= SCALING_LIST_1D_START_16x16) ? getScalingListDC(scalingListId) : -1), scalingListId, BitsCount);
03946   bestBitsCount = BitsCount;
03947 
03948   for (int predListIdx = (int)scalingListId; predListIdx >= 0; predListIdx--)
03949   {
03950 
03951     int matrixSize = (scalingListId < SCALING_LIST_1D_START_4x4) ? 2 : (scalingListId < SCALING_LIST_1D_START_8x8) ? 4 : 8;
03952     int predMatrixSize = (predListIdx < SCALING_LIST_1D_START_4x4) ? 2 : (predListIdx < SCALING_LIST_1D_START_8x8) ? 4 : 8;
03953     if (((scalingListId == SCALING_LIST_1D_START_2x2 || scalingListId == SCALING_LIST_1D_START_4x4 || scalingListId == SCALING_LIST_1D_START_8x8) && predListIdx != (int)scalingListId) || matrixSize != predMatrixSize)
03954       continue;
03955     const int* refScalingList = (scalingListId == predListIdx) ? getScalingListDefaultAddress(predListIdx) : getScalingListAddress(predListIdx);
03956     const int refDC = (predListIdx < SCALING_LIST_1D_START_16x16) ? refScalingList[0] : (scalingListId == predListIdx) ? 16 : getScalingListDC(predListIdx);
03957     if (!::memcmp(getScalingListAddress(scalingListId), refScalingList, sizeof(int)*matrixSize*matrixSize) // check value of matrix
03958       // check DC value
03959       && (scalingListId < SCALING_LIST_1D_START_16x16 || getScalingListDC(scalingListId) == refDC))
03960     {
03961       //copy mode
03962       setRefMatrixId(scalingListId, predListIdx);
03963       setScalingListCopyModeFlag(scalingListId, true);
03964       setScalingListPreditorModeFlag(scalingListId, false);
03965       return;
03966     }
03967     else
03968     {
03969       //predictor mode
03970       //use previously coded matrix as a predictor
03971       CheckBestPredScalingList(scalingListId, predListIdx, BitsCount);
03972       if (BitsCount < bestBitsCount)
03973       {
03974         bestBitsCount = BitsCount;
03975         setScalingListCopyModeFlag(scalingListId, false);
03976         setScalingListPreditorModeFlag(scalingListId, true);
03977         setRefMatrixId(scalingListId, predListIdx);
03978       }
03979     }
03980   }
03981   setScalingListCopyModeFlag(scalingListId, false);
03982 }
03983 
03984 static void outputScalingListHelp(std::ostream &os)
03985 {
03986   os << "The scaling list file specifies all matrices and their DC values; none can be missing,\n"
03987          "but their order is arbitrary.\n\n"
03988          "The matrices are specified by:\n"
03989          "<matrix name><unchecked data>\n"
03990          "  <value>,<value>,<value>,....\n\n"
03991          "  Line-feeds can be added arbitrarily between values, and the number of values needs to be\n"
03992          "  at least the number of entries for the matrix (superfluous entries are ignored).\n"
03993          "  The <unchecked data> is text on the same line as the matrix that is not checked\n"
03994          "  except to ensure that the matrix name token is unique. It is recommended that it is ' ='\n"
03995          "  The values in the matrices are the absolute values (0-255), not the delta values as\n"
03996          "  exchanged between the encoder and decoder\n\n"
03997          "The DC values (for matrix sizes larger than 8x8) are specified by:\n"
03998          "<matrix name>_DC<unchecked data>\n"
03999          "  <value>\n";
04000 
04001   os << "The permitted matrix names are:\n";
04002   for (uint32_t sizeIdc = SCALING_LIST_2x2; sizeIdc <= SCALING_LIST_64x64; sizeIdc++)
04003   {
04004     for (uint32_t listIdc = 0; listIdc < SCALING_LIST_NUM; listIdc++)
04005     {
04006       if (!(((sizeIdc == SCALING_LIST_64x64) && (listIdc % (SCALING_LIST_NUM / SCALING_LIST_PRED_MODES) != 0)) || ((sizeIdc == SCALING_LIST_2x2) && (listIdc % (SCALING_LIST_NUM / SCALING_LIST_PRED_MODES) == 0))))
04007       {
04008         os << "  " << MatrixType[sizeIdc][listIdc] << '\n';
04009       }
04010     }
04011   }
04012 }
04013 
04014 void ScalingList::outputScalingLists(std::ostream &os) const
04015 {
04016   int scalingListId = 0;
04017   for (uint32_t sizeIdc = SCALING_LIST_2x2; sizeIdc <= SCALING_LIST_64x64; sizeIdc++)
04018   {
04019     const uint32_t size = (sizeIdc == 1) ? 2 : ((sizeIdc == 2) ? 4 : 8);
04020     for(uint32_t listIdc = 0; listIdc < SCALING_LIST_NUM; listIdc++)
04021     {
04022       if (!((sizeIdc== SCALING_LIST_64x64 && listIdc % (SCALING_LIST_NUM / SCALING_LIST_PRED_MODES) != 0) || (sizeIdc == SCALING_LIST_2x2 && listIdc < 4)))
04023       {
04024         const int *src = getScalingListAddress(scalingListId);
04025         os << (MatrixType[sizeIdc][listIdc]) << " =\n  ";
04026         for(uint32_t y=0; y<size; y++)
04027         {
04028           for(uint32_t x=0; x<size; x++, src++)
04029           {
04030             os << std::setw(3) << (*src) << ", ";
04031           }
04032           os << (y+1<size?"\n  ":"\n");
04033         }
04034         if(sizeIdc > SCALING_LIST_8x8)
04035         {
04036           os << MatrixType_DC[sizeIdc][listIdc] << " = \n  " << std::setw(3) << getScalingListDC(scalingListId) << "\n";
04037         }
04038         os << "\n";
04039         scalingListId++;
04040       }
04041     }
04042   }
04043 }
04044 
04045 bool ScalingList::xParseScalingList(const std::string &fileName)
04046 {
04047   static const int LINE_SIZE=1024;
04048   FILE *fp = NULL;
04049   char line[LINE_SIZE];
04050 
04051   if (fileName.empty())
04052   {
04053     msg( ERROR, "Error: no scaling list file specified. Help on scaling lists being output\n");
04054     outputScalingListHelp(std::cout);
04055     std::cout << "\n\nExample scaling list file using default values:\n\n";
04056     outputScalingLists(std::cout);
04057     return true;
04058   }
04059   else if ((fp = fopen(fileName.c_str(),"r")) == (FILE*)NULL)
04060   {
04061     msg( ERROR, "Error: cannot open scaling list file %s for reading\n", fileName.c_str());
04062     return true;
04063   }
04064 
04065   int scalingListId = 0;
04066   for (uint32_t sizeIdc = SCALING_LIST_2x2; sizeIdc <= SCALING_LIST_64x64; sizeIdc++)//2x2-128x128
04067   {
04068     const uint32_t size = std::min(MAX_MATRIX_COEF_NUM,(int)g_scalingListSize[sizeIdc]);
04069 
04070     for(uint32_t listIdc = 0; listIdc < SCALING_LIST_NUM; listIdc++)
04071     {
04072 
04073       if ((sizeIdc == SCALING_LIST_64x64 && listIdc % (SCALING_LIST_NUM / SCALING_LIST_PRED_MODES) != 0) || (sizeIdc == SCALING_LIST_2x2 && listIdc < 4))
04074       {
04075         continue;
04076       }
04077       else
04078       {
04079         int * const src = getScalingListAddress(scalingListId);
04080         {
04081           fseek(fp, 0, SEEK_SET);
04082           bool bFound=false;
04083           while ((!feof(fp)) && (!bFound))
04084           {
04085             char *ret = fgets(line, LINE_SIZE, fp);
04086             char *findNamePosition= ret==NULL ? NULL : strstr(line, MatrixType[sizeIdc][listIdc]);
04087             // This could be a match against the DC string as well, so verify it isn't
04088             if (findNamePosition!= NULL && (MatrixType_DC[sizeIdc][listIdc]==NULL || strstr(line, MatrixType_DC[sizeIdc][listIdc])==NULL))
04089             {
04090               bFound=true;
04091             }
04092           }
04093           if (!bFound)
04094           {
04095             msg( ERROR, "Error: cannot find Matrix %s from scaling list file %s\n", MatrixType[sizeIdc][listIdc], fileName.c_str());
04096             return true;
04097 
04098           }
04099         }
04100         for (uint32_t i=0; i<size; i++)
04101         {
04102           int data;
04103           if (fscanf(fp, "%d,", &data)!=1)
04104           {
04105             msg( ERROR, "Error: cannot read value #%d for Matrix %s from scaling list file %s at file position %ld\n", i, MatrixType[sizeIdc][listIdc], fileName.c_str(), ftell(fp));
04106             return true;
04107           }
04108           if (data<0 || data>255)
04109           {
04110             msg( ERROR, "Error: QMatrix entry #%d of value %d for Matrix %s from scaling list file %s at file position %ld is out of range (0 to 255)\n", i, data, MatrixType[sizeIdc][listIdc], fileName.c_str(), ftell(fp));
04111             return true;
04112           }
04113           src[i] = data;
04114         }
04115 
04116         //set DC value for default matrix check
04117         setScalingListDC(scalingListId, src[0]);
04118 
04119         if(sizeIdc > SCALING_LIST_8x8)
04120         {
04121           {
04122             fseek(fp, 0, SEEK_SET);
04123             bool bFound=false;
04124             while ((!feof(fp)) && (!bFound))
04125             {
04126               char *ret = fgets(line, LINE_SIZE, fp);
04127               char *findNamePosition= ret==NULL ? NULL : strstr(line, MatrixType_DC[sizeIdc][listIdc]);
04128               if (findNamePosition!= NULL)
04129               {
04130                 // This won't be a match against the non-DC string.
04131                 bFound=true;
04132               }
04133             }
04134             if (!bFound)
04135             {
04136               msg( ERROR, "Error: cannot find DC Matrix %s from scaling list file %s\n", MatrixType_DC[sizeIdc][listIdc], fileName.c_str());
04137               return true;
04138             }
04139           }
04140           int data;
04141           if (fscanf(fp, "%d,", &data)!=1)
04142           {
04143             msg( ERROR, "Error: cannot read DC %s from scaling list file %s at file position %ld\n", MatrixType_DC[sizeIdc][listIdc], fileName.c_str(), ftell(fp));
04144             return true;
04145           }
04146           if (data<0 || data>255)
04147           {
04148             msg( ERROR, "Error: DC value %d for Matrix %s from scaling list file %s at file position %ld is out of range (0 to 255)\n", data, MatrixType[sizeIdc][listIdc], fileName.c_str(), ftell(fp));
04149             return true;
04150           }
04151           //overwrite DC value when size of matrix is larger than 16x16
04152           setScalingListDC(scalingListId, data);
04153         }
04154       }
04155       scalingListId++;
04156     }
04157   }
04158 //  std::cout << "\n\nRead scaling lists of:\n\n";
04159 //  outputScalingLists(std::cout);
04160 
04161   fclose(fp);
04162   return false;
04163 }
04164 
04165 
04171 const int* ScalingList::getScalingListDefaultAddress(uint32_t scalingListId)
04172 {
04173   const int *src = 0;
04174   int sizeId = (scalingListId < SCALING_LIST_1D_START_8x8) ? 2 : 3;
04175   switch (sizeId)
04176   {
04177     case SCALING_LIST_1x1:
04178     case SCALING_LIST_2x2:
04179     case SCALING_LIST_4x4:
04180       src = g_quantTSDefault4x4;
04181       break;
04182     case SCALING_LIST_8x8:
04183     case SCALING_LIST_16x16:
04184     case SCALING_LIST_32x32:
04185     case SCALING_LIST_64x64:
04186     case SCALING_LIST_128x128:
04187       src = g_quantInterDefault8x8;
04188       break;
04189     default:
04190       THROW( "Invalid scaling list" );
04191       src = NULL;
04192       break;
04193   }
04194   return src;
04195 }
04196 
04201 void ScalingList::processDefaultMatrix(uint32_t scalingListId)
04202 {
04203   int matrixSize = (scalingListId < SCALING_LIST_1D_START_4x4) ? 2 : (scalingListId < SCALING_LIST_1D_START_8x8) ? 4 : 8;
04204   ::memcpy(getScalingListAddress(scalingListId), getScalingListDefaultAddress(scalingListId), sizeof(int)*matrixSize*matrixSize);
04205   setScalingListDC(scalingListId, SCALING_LIST_DC);
04206 }
