04210 void ScalingList::checkDcOfMatrix()
04211 {
04212   for (uint32_t scalingListId = 0; scalingListId < 28; scalingListId++)
04213   {
04214     //check default matrix?
04215     if (getScalingListDC(scalingListId) == 0)
04216     {
04217       processDefaultMatrix(scalingListId);
04218     }
04219   }
04220 }
