04272 
04273 void Slice::scaleRefPicList( Picture *scaledRefPic[ ], PicHeader *picHeader, APS** apss, APS* lmcsAps, APS* scalingListAps, const bool isDecoder )
04274 {
04275   int i;
04276   const SPS* sps = getSPS();
04277   const PPS* pps = getPPS();
04278 
04279   bool refPicIsSameRes = false;
04280 
04281   // this is needed for IBC
04282   m_pcPic->unscaledPic = m_pcPic;
04283 
04284   if( m_eSliceType == I_SLICE )
04285   {
04286     return;
04287   }
04288 
04289   freeScaledRefPicList( scaledRefPic );
04290 
04291   for( int refList = 0; refList < NUM_REF_PIC_LIST_01; refList++ )
04292   {
04293     if( refList == 1 && m_eSliceType != B_SLICE )
04294     {
04295       continue;
04296     }
04297 
04298     for( int rIdx = 0; rIdx < m_aiNumRefIdx[refList]; rIdx++ )
04299     {
04300       // if rescaling is needed, otherwise just reuse the original picture pointer; it is needed for motion field, otherwise motion field requires a copy as well
04301       // reference resampling for the whole picture is not applied at decoder
04302 
04303       int xScale, yScale;
04304       CU::getRprScaling( sps, pps, m_apcRefPicList[refList][rIdx], xScale, yScale );
04305       m_scalingRatio[refList][rIdx] = std::pair<int, int>( xScale, yScale );
04306 
04307       CHECK( m_apcRefPicList[refList][rIdx]->unscaledPic == nullptr, "unscaledPic is not properly set" );
04308 
04309       if( m_apcRefPicList[refList][rIdx]->isRefScaled( pps ) == false )
04310       {
04311         refPicIsSameRes = true;
04312       }
04313 
04314       if( m_scalingRatio[refList][rIdx] == SCALE_1X || isDecoder )
04315       {
04316         m_scaledRefPicList[refList][rIdx] = m_apcRefPicList[refList][rIdx];
04317       }
04318       else
04319       {
04320         int poc = m_apcRefPicList[refList][rIdx]->getPOC();
04321         int layerId = m_apcRefPicList[refList][rIdx]->layerId;
04322 
04323         // check whether the reference picture has already been scaled
04324         for( i = 0; i < MAX_NUM_REF; i++ )
04325         {
04326           if( scaledRefPic[i] != nullptr && scaledRefPic[i]->poc == poc && scaledRefPic[i]->layerId == layerId )
04327           {
04328             break;
04329           }
04330         }
04331 
04332         if( i == MAX_NUM_REF )
04333         {
04334           int j;
04335           // search for unused Picture structure in scaledRefPic
04336           for( j = 0; j < MAX_NUM_REF; j++ )
04337           {
04338             if( scaledRefPic[j] == nullptr )
04339             {
04340               break;
04341             }
04342           }
04343 
04344           CHECK( j >= MAX_NUM_REF, "scaledRefPic can not hold all reference pictures!" );
04345 
04346           if( j >= MAX_NUM_REF )
04347           {
04348             j = 0;
04349           }
04350 
04351           if( scaledRefPic[j] == nullptr )
04352           {
04353             scaledRefPic[j] = new Picture;
04354 
04355             scaledRefPic[j]->setBorderExtension( false );
04356             scaledRefPic[j]->reconstructed = false;
04357             scaledRefPic[j]->referenced = true;
04358 
04359             scaledRefPic[j]->finalInit( m_pcPic->cs->vps, *sps, *pps, picHeader, apss, lmcsAps, scalingListAps );
04360 
04361             scaledRefPic[j]->poc = NOT_VALID;
04362 
04363             scaledRefPic[j]->create( sps->getChromaFormatIdc(), Size( pps->getPicWidthInLumaSamples(), pps->getPicHeightInLumaSamples() ), sps->getMaxCUWidth(), sps->getMaxCUWidth() + 16, isDecoder, layerId );
04364           }
04365 
04366           scaledRefPic[j]->poc = poc;
04367           scaledRefPic[j]->longTerm = m_apcRefPicList[refList][rIdx]->longTerm;
04368 
04369           // rescale the reference picture
04370           const bool downsampling = m_apcRefPicList[refList][rIdx]->getRecoBuf().Y().width >= scaledRefPic[j]->getRecoBuf().Y().width && m_apcRefPicList[refList][rIdx]->getRecoBuf().Y().height >= scaledRefPic[j]->getRecoBuf().Y().height;
04371           Picture::rescalePicture( m_scalingRatio[refList][rIdx],
04372                                    m_apcRefPicList[refList][rIdx]->getRecoBuf(), m_apcRefPicList[refList][rIdx]->slices[0]->getPPS()->getScalingWindow(),
04373                                    scaledRefPic[j]->getRecoBuf(), pps->getScalingWindow(),
04374                                    sps->getChromaFormatIdc(), sps->getBitDepths(), true, downsampling,
04375                                    sps->getHorCollocatedChromaFlag(), sps->getVerCollocatedChromaFlag() );
04376           scaledRefPic[j]->unscaledPic = m_apcRefPicList[refList][rIdx];
04377           scaledRefPic[j]->extendPicBorder( getPPS() );
04378 
04379           m_scaledRefPicList[refList][rIdx] = scaledRefPic[j];
04380         }
04381         else
04382         {
04383           m_scaledRefPicList[refList][rIdx] = scaledRefPic[i];
04384         }
04385       }
04386     }
04387   }
04388 
04389   // make the scaled reference picture list as the default reference picture list
04390   for( int refList = 0; refList < NUM_REF_PIC_LIST_01; refList++ )
04391   {
04392     if( refList == 1 && m_eSliceType != B_SLICE )
04393     {
04394       continue;
04395     }
04396 
04397     for( int rIdx = 0; rIdx < m_aiNumRefIdx[refList]; rIdx++ )
04398     {
04399       m_savedRefPicList[refList][rIdx] = m_apcRefPicList[refList][rIdx];
04400       m_apcRefPicList[refList][rIdx] = m_scaledRefPicList[refList][rIdx];
04401 
04402       // allow the access of the unscaled version in xPredInterBlk()
04403       m_apcRefPicList[refList][rIdx]->unscaledPic = m_savedRefPicList[refList][rIdx];
04404     }
04405   }
04406 
04407   //Make sure that TMVP is disabled when there are no reference pictures with the same resolution
04408   if(!refPicIsSameRes)
04409   {
04410     CHECK(getPicHeader()->getEnableTMVPFlag() != 0, "TMVP cannot be enabled in pictures that have no reference pictures with the same resolution")
04411   }
04412 }
04413 
04414 void Slice::freeScaledRefPicList( Picture *scaledRefPic[] )
04415 {
04416   if( m_eSliceType == I_SLICE )
04417   {
04418     return;
04419   }
04420   for( int i = 0; i < MAX_NUM_REF; i++ )
04421   {
04422     if( scaledRefPic[i] != nullptr )
04423     {
04424       scaledRefPic[i]->destroy();
04425       scaledRefPic[i] = nullptr;
04426     }
04427   }
04428 }
04429 
04430 bool Slice::checkRPR()
04431 {
04432   const PPS* pps = getPPS();
04433 
04434   for( int refList = 0; refList < NUM_REF_PIC_LIST_01; refList++ )
04435   {
04436 
04437     if( refList == 1 && m_eSliceType != B_SLICE )
04438     {
04439       continue;
04440     }
04441 
04442     for( int rIdx = 0; rIdx < m_aiNumRefIdx[refList]; rIdx++ )
04443     {
04444       if( m_scaledRefPicList[refList][rIdx]->cs->pcv->lumaWidth != pps->getPicWidthInLumaSamples() || m_scaledRefPicList[refList][rIdx]->cs->pcv->lumaHeight != pps->getPicHeightInLumaSamples() )
04445       {
04446         return true;
04447       }
04448     }
04449   }
04450 
04451   return false;
04452 }
04453 
04454 bool             operator == (const ConstraintInfo& op1, const ConstraintInfo& op2)
04455 {
04456   if( op1.m_intraOnlyConstraintFlag                      != op2.m_intraOnlyConstraintFlag                        ) return false;
04457   if( op1.m_maxBitDepthConstraintIdc                     != op2.m_maxBitDepthConstraintIdc                       ) return false;
04458   if( op1.m_maxChromaFormatConstraintIdc                 != op2.m_maxChromaFormatConstraintIdc                   ) return false;
04459   if( op1.m_onePictureOnlyConstraintFlag                 != op2.m_onePictureOnlyConstraintFlag                   ) return false;
04460   if( op1.m_lowerBitRateConstraintFlag                   != op2.m_lowerBitRateConstraintFlag                     ) return false;
04461   if (op1.m_allLayersIndependentConstraintFlag           != op2.m_allLayersIndependentConstraintFlag             ) return false;
04462   if (op1.m_noMrlConstraintFlag                          != op2.m_noMrlConstraintFlag                            ) return false;
04463   if (op1.m_noIspConstraintFlag                          != op2.m_noIspConstraintFlag                            ) return false;
04464   if (op1.m_noMipConstraintFlag                          != op2.m_noMipConstraintFlag                            ) return false;
04465   if (op1.m_noLfnstConstraintFlag                        != op2.m_noLfnstConstraintFlag                          ) return false;
04466   if (op1.m_noMmvdConstraintFlag                         != op2.m_noMmvdConstraintFlag                           ) return false;
04467   if (op1.m_noSmvdConstraintFlag                         != op2.m_noSmvdConstraintFlag                           ) return false;
04468   if (op1.m_noProfConstraintFlag                         != op2.m_noProfConstraintFlag                           ) return false;
04469   if (op1.m_noPaletteConstraintFlag                      != op2.m_noPaletteConstraintFlag                        ) return false;
04470   if (op1.m_noActConstraintFlag                          != op2.m_noActConstraintFlag                            ) return false;
04471   if (op1.m_noLmcsConstraintFlag                         != op2.m_noLmcsConstraintFlag                           ) return false;
04472   if (op1.m_noExplicitScaleListConstraintFlag            != op2.m_noExplicitScaleListConstraintFlag              ) return false;
04473   if (op1.m_noVirtualBoundaryConstraintFlag              != op2.m_noVirtualBoundaryConstraintFlag                ) return false;
04474   if (op1.m_noChromaQpOffsetConstraintFlag               != op2.m_noChromaQpOffsetConstraintFlag                 ) return false;
04475   if (op1.m_noRprConstraintFlag                          != op2.m_noRprConstraintFlag                            ) return false;
04476   if (op1.m_noResChangeInClvsConstraintFlag              != op2.m_noResChangeInClvsConstraintFlag                ) return false;
04477   if (op1.m_noMttConstraintFlag                          != op2.m_noMttConstraintFlag                            ) return false;
04478   if( op1.m_noQtbttDualTreeIntraConstraintFlag           != op2.m_noQtbttDualTreeIntraConstraintFlag             ) return false;
04479   if( op1.m_noPartitionConstraintsOverrideConstraintFlag != op2.m_noPartitionConstraintsOverrideConstraintFlag   ) return false;
04480   if( op1.m_noSaoConstraintFlag                          != op2.m_noSaoConstraintFlag                            ) return false;
04481   if( op1.m_noAlfConstraintFlag                          != op2.m_noAlfConstraintFlag                            ) return false;
04482   if( op1.m_noCCAlfConstraintFlag                        != op2.m_noCCAlfConstraintFlag                          ) return false;
04483   if (op1.m_noWeightedPredictionConstraintFlag           != op2.m_noWeightedPredictionConstraintFlag             ) return false;
04484   if( op1.m_noRefWraparoundConstraintFlag                != op2.m_noRefWraparoundConstraintFlag                  ) return false;
04485   if( op1.m_noTemporalMvpConstraintFlag                  != op2.m_noTemporalMvpConstraintFlag                    ) return false;
04486   if( op1.m_noSbtmvpConstraintFlag                       != op2.m_noSbtmvpConstraintFlag                         ) return false;
04487   if( op1.m_noAmvrConstraintFlag                         != op2.m_noAmvrConstraintFlag                           ) return false;
04488   if( op1.m_noBdofConstraintFlag                         != op2.m_noBdofConstraintFlag                           ) return false;
04489   if( op1.m_noDmvrConstraintFlag                         != op2.m_noDmvrConstraintFlag                           ) return false;
04490   if( op1.m_noCclmConstraintFlag                         != op2.m_noCclmConstraintFlag                           ) return false;
04491   if( op1.m_noMtsConstraintFlag                          != op2.m_noMtsConstraintFlag                            ) return false;
04492   if( op1.m_noSbtConstraintFlag                          != op2.m_noSbtConstraintFlag                            ) return false;
04493   if( op1.m_noAffineMotionConstraintFlag                 != op2.m_noAffineMotionConstraintFlag                   ) return false;
04494   if( op1.m_noBcwConstraintFlag                          != op2.m_noBcwConstraintFlag                            ) return false;
04495   if( op1.m_noIbcConstraintFlag                          != op2.m_noIbcConstraintFlag                            ) return false;
04496   if( op1.m_noCiipConstraintFlag                         != op2.m_noCiipConstraintFlag                           ) return false;
04497   if( op1.m_noLadfConstraintFlag                         != op2.m_noLadfConstraintFlag                           ) return false;
04498   if( op1.m_noTransformSkipConstraintFlag                != op2.m_noTransformSkipConstraintFlag                  ) return false;
04499   if( op1.m_noBDPCMConstraintFlag                        != op2.m_noBDPCMConstraintFlag                          ) return false;
04500   if( op1.m_noJointCbCrConstraintFlag                    != op2.m_noJointCbCrConstraintFlag                      ) return false;
04501   if( op1.m_noCuQpDeltaConstraintFlag                    != op2.m_noCuQpDeltaConstraintFlag                      ) return false;
04502   if( op1.m_noDepQuantConstraintFlag                     != op2.m_noDepQuantConstraintFlag                       ) return false;
04503   if( op1.m_noSignDataHidingConstraintFlag               != op2.m_noSignDataHidingConstraintFlag                 ) return false;
04504   if( op1.m_noTrailConstraintFlag                        != op2.m_noTrailConstraintFlag                          ) return false;
04505   if( op1.m_noStsaConstraintFlag                         != op2.m_noStsaConstraintFlag                           ) return false;
04506   if( op1.m_noRaslConstraintFlag                         != op2.m_noRaslConstraintFlag                           ) return false;
04507   if( op1.m_noRadlConstraintFlag                         != op2.m_noRadlConstraintFlag                           ) return false;
04508   if( op1.m_noIdrConstraintFlag                          != op2.m_noIdrConstraintFlag                            ) return false;
04509   if( op1.m_noCraConstraintFlag                          != op2.m_noCraConstraintFlag                            ) return false;
04510   if( op1.m_noGdrConstraintFlag                          != op2.m_noGdrConstraintFlag                            ) return false;
04511   if( op1.m_noApsConstraintFlag                          != op2.m_noApsConstraintFlag                            ) return false;
04512   return true;
04513 }
04514 bool             operator != (const ConstraintInfo& op1, const ConstraintInfo& op2)
04515 {
04516   return !(op1 == op2);
04517 }
04518 
04519 bool             operator == (const ProfileTierLevel& op1, const ProfileTierLevel& op2)
04520 {
04521   if (op1.m_tierFlag        != op2.m_tierFlag) return false;
04522   if (op1.m_profileIdc      != op2.m_profileIdc) return false;
04523   if (op1.m_numSubProfile   != op2.m_numSubProfile) return false;
04524   if (op1.m_levelIdc        != op2.m_levelIdc) return false;
04525   if (op1.m_frameOnlyConstraintFlag != op2.m_frameOnlyConstraintFlag) return false;
04526   if (op1.m_multiLayerEnabledFlag   != op2.m_multiLayerEnabledFlag) return false;
04527   if (op1.m_constraintInfo  != op2.m_constraintInfo) return false;
04528   if (op1.m_subProfileIdc   != op2.m_subProfileIdc) return false;
04529 
04530   for (int i = 0; i < MAX_TLAYER - 1; i++)
04531   {
04532     if (op1.m_subLayerLevelPresentFlag[i] != op2.m_subLayerLevelPresentFlag[i])
04533     {
04534       return false;
04535     }
04536   }
04537   for (int i = 0; i < MAX_TLAYER; i++)
04538   {
04539     if (op1.m_subLayerLevelIdc[i] != op2.m_subLayerLevelIdc[i])
04540     {
04541       return false;
04542     }
04543   }
04544   return true;
04545 }
04546 bool             operator != (const ProfileTierLevel& op1, const ProfileTierLevel& op2)
04547 {
04548   return !(op1 == op2);
04549 }
04550 
04551 bool Slice::isLastSliceInSubpic()
04552 {
04553   CHECK(m_pcPPS == NULL, "PPS pointer not initialized");
04554 
04555   int lastCTUAddrInSlice = m_sliceMap.getCtuAddrList().back();
04556 
04557   if (m_pcPPS->getNumSubPics() > 1)
04558   {
04559     const SubPic& subpic = m_pcPPS->getSubPic(m_pcPPS->getSubPicIdxFromSubPicId(getSliceSubPicId()));
04560     return subpic.isLastCTUinSubPic(lastCTUAddrInSlice);
04561   }
04562   else
04563   {
04564     const CodingStructure *cs = m_pcPic->cs;
04565     const PreCalcValues* pcv = cs->pcv;
04566     const uint32_t picSizeInCtus   = pcv->heightInCtus * pcv->widthInCtus;
04567     return lastCTUAddrInSlice == (picSizeInCtus-1);
04568   }
04569 }
